css:
@property --dbs-bridge-qr { syntax: "<number>"; inherits: true; initial-value: 0; }
@keyframes dbs-bridge-rise { from { transform: scaleY(0); } }
@keyframes dbs-bridge-fade { from { opacity: 0; } }
@keyframes dbs-bridge-lift { from { opacity: 0; transform: translateY(6px); filter: blur(3px); } }
@keyframes dbs-bridge-row { from { opacity: 0; transform: translateY(10px); } }
@keyframes dbs-bridge-vt-out { to { opacity: 0; transform: translateY(-6px); } }
@keyframes dbs-bridge-vt-in { from { opacity: 0; transform: translateY(10px); } }

html:has(.dbs-bridge)::view-transition-old(dbs-bridge-main) { animation: 140ms cubic-bezier(.4,0,1,1) both dbs-bridge-vt-out; }
html:has(.dbs-bridge)::view-transition-new(dbs-bridge-main) { animation: 360ms cubic-bezier(.2,.8,.2,1) 60ms both dbs-bridge-vt-in; }

.dbs-bridge *, .dbs-bridge *::before, .dbs-bridge *::after { box-sizing: border-box; }

.dbs-bridge {
  --dbs-bridge-paper: oklch(0.972 0.009 84);
  --dbs-bridge-ink: oklch(0.25 0.02 62);
  --dbs-bridge-up: oklch(0.56 0.115 158);
  --dbs-bridge-down: oklch(0.6 0.16 34);

  --dbs-bridge-panel: color-mix(in oklch, var(--dbs-bridge-paper), white 62%);
  --dbs-bridge-side-bg: color-mix(in oklch, var(--dbs-bridge-ink) 4.5%, var(--dbs-bridge-paper));
  --dbs-bridge-line: color-mix(in oklch, var(--dbs-bridge-ink) 11%, transparent);
  --dbs-bridge-line-2: color-mix(in oklch, var(--dbs-bridge-ink) 22%, transparent);
  --dbs-bridge-mute: color-mix(in oklch, var(--dbs-bridge-ink) 56%, var(--dbs-bridge-paper));
  --dbs-bridge-faint: color-mix(in oklch, var(--dbs-bridge-ink) 5%, transparent);
  --dbs-bridge-up-2: color-mix(in oklch, var(--dbs-bridge-up) 62%, var(--dbs-bridge-paper));
  --dbs-bridge-up-3: color-mix(in oklch, var(--dbs-bridge-up) 36%, var(--dbs-bridge-paper));
  --dbs-bridge-down-2: color-mix(in oklch, var(--dbs-bridge-down) 55%, var(--dbs-bridge-paper));
  --dbs-bridge-ease: cubic-bezier(.2, .8, .2, 1);
  --dbs-bridge-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 20.4%, 1.043 24.3%, 1.035 28.1%, 1.007 36.4%, .996 45.6%, 1.001 66.1%, 1);
  --dbs-bridge-mono: ui-monospace, Menlo, "SF Mono", Consolas, monospace;

  position: relative;
  width: 100%;
  height: var(--dbs-bridge-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  border-radius: 14px;
  border: 1px solid var(--dbs-bridge-line);
  background: var(--dbs-bridge-paper);
  color: var(--dbs-bridge-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased;

  button { font: inherit; color: inherit; }
  :focus-visible { outline: 2px solid var(--dbs-bridge-ink); outline-offset: 2px; border-radius: 6px; }
  svg { display: block; }

  .dbs-bridge-app {
    height: 100%;
    display: grid;
    grid-template-columns: 208px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-areas: "side head" "side main";
  }

  /* ---------- sidebar ---------- */
  .dbs-bridge-side {
    grid-area: side;
    display: flex; flex-direction: column; gap: 22px;
    padding: 18px 12px;
    background: var(--dbs-bridge-side-bg);
    border-right: 1px solid var(--dbs-bridge-line);
  }
  .dbs-bridge-brand {
    display: flex; align-items: center; gap: 10px; padding: 0 6px;
    svg { width: 30px; height: 30px; padding: 6px; border-radius: 9px; background: var(--dbs-bridge-ink); fill: none; stroke: var(--dbs-bridge-paper); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
    b { display: block; font-weight: 680; letter-spacing: -.01em; }
    small { display: block; color: var(--dbs-bridge-mute); font-size: 11px; }
  }
  .dbs-bridge-nav {
    position: relative; display: grid; gap: 2px;
    &::before {
      content: ""; position: absolute; left: 0; top: 0; height: 36px; width: 100%;
      border-radius: 9px; background: var(--dbs-bridge-panel);
      box-shadow: 0 1px 0 var(--dbs-bridge-line), 0 0 0 1px var(--dbs-bridge-line);
      transform: translateY(calc(var(--sel) * 38px));
      transition: transform .55s var(--dbs-bridge-spring);
    }
    button {
      position: relative; display: flex; align-items: center; gap: 10px;
      height: 36px; padding: 0 10px; border: 0; border-radius: 9px; background: none;
      color: var(--dbs-bridge-mute); cursor: pointer; text-align: left; font-weight: 550;
      transition: color .2s;
      svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; flex: none; }
      &:hover { color: var(--dbs-bridge-ink); }
      &[aria-selected="true"] { color: var(--dbs-bridge-ink); }
    }
  }
  .dbs-bridge-fresh {
    margin: auto 6px 0; font-size: 11px; color: var(--dbs-bridge-mute); line-height: 1.4;
    span, b { display: block; }
    b { color: var(--dbs-bridge-ink); font-weight: 600; }
  }

  /* ---------- header ---------- */
  .dbs-bridge-head {
    grid-area: head;
    display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 12px 18px;
    padding: 18px 20px 12px;
  }
  .dbs-bridge-title {
    h2 { margin: 0; font-size: clamp(19px, 2.1cqi, 25px); font-weight: 680; letter-spacing: -.022em; line-height: 1.1; text-wrap: balance; }
  }
  .dbs-bridge-sub { margin: 4px 0 0; color: var(--dbs-bridge-mute); text-wrap: pretty; }
  .dbs-bridge-ctrls { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }
  .dbs-bridge-seg {
    position: relative; display: grid; grid-template-columns: repeat(3, auto); padding: 3px;
    border-radius: 10px; background: var(--dbs-bridge-faint); box-shadow: inset 0 0 0 1px var(--dbs-bridge-line);
    button {
      position: relative; z-index: 1; border: 0; background: none; padding: 5px 12px; border-radius: 7px;
      color: var(--dbs-bridge-mute); cursor: pointer; font-weight: 550; white-space: nowrap; transition: color .2s;
      &[aria-checked="true"] { color: var(--dbs-bridge-ink); }
    }
    i {
      position: absolute; top: 3px; bottom: 3px; left: 0; width: var(--w, 40px);
      transform: translateX(var(--x, 3px)); border-radius: 7px;
      background: var(--dbs-bridge-panel); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbs-bridge-ink) 14%, transparent), 0 0 0 1px var(--dbs-bridge-line);
      transition: transform .5s var(--dbs-bridge-spring), width .5s var(--dbs-bridge-spring);
    }
  }
  .dbs-bridge-step {
    display: flex; align-items: center; gap: 2px; padding: 3px; border-radius: 10px; box-shadow: inset 0 0 0 1px var(--dbs-bridge-line);
    button {
      width: 28px; height: 28px; display: grid; place-items: center; border: 0; border-radius: 7px; background: none; cursor: pointer; color: var(--dbs-bridge-ink);
      svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
      &:hover:not(:disabled) { background: var(--dbs-bridge-faint); }
      &:disabled { opacity: .3; cursor: default; }
    }
  }
  .dbs-bridge-mo { min-width: 72px; text-align: center; font-weight: 600; font-family: var(--dbs-bridge-mono); font-size: 12px; }

  /* ---------- main + views ---------- */
  .dbs-bridge-main {
    grid-area: main; min-height: 0; overflow: auto; padding: 0 20px 18px;
    scrollbar-width: thin; scrollbar-color: var(--dbs-bridge-line-2) transparent;
  }
  .dbs-bridge-view[hidden] { display: none !important; }
  .dbs-bridge-panel {
    background: var(--dbs-bridge-panel); border: 1px solid var(--dbs-bridge-line); border-radius: 12px;
    box-shadow: 0 1px 0 color-mix(in oklch, var(--dbs-bridge-ink) 4%, transparent);
    min-width: 0;
  }
  .dbs-bridge-ph {
    display: flex; align-items: baseline; justify-content: space-between; gap: 10px; padding: 12px 14px 0;
    h3 { margin: 0; font-size: 11px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dbs-bridge-mute); }
  }
  .dbs-bridge-hint { margin: 0; font-size: 11px; color: var(--dbs-bridge-mute); }

  .dbs-bridge-v-bridge {
    height: 100%;
    display: grid; gap: 12px;
    grid-template-columns: minmax(0, 1fr) minmax(250px, 31%);
    grid-template-rows: auto minmax(0, 1fr) auto;
    grid-template-areas: "kpi kpi" "chart movers" "scrub movers";
  }
  .dbs-bridge-kpis { grid-area: kpi; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
  .dbs-bridge-kpi {
    padding: 11px 14px 12px; border-radius: 12px; border: 1px solid var(--dbs-bridge-line); background: var(--dbs-bridge-panel);
    h4 { margin: 0; font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dbs-bridge-mute); }
  }
  .dbs-bridge-kv { margin: 4px 0 2px; font-size: clamp(19px, 2.3cqi, 27px); font-weight: 640; letter-spacing: -.025em; line-height: 1.05; }
  .dbs-bridge-kd { margin: 0; font-size: 11.5px; color: var(--dbs-bridge-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    b { font-weight: 650; }
    .is-up { color: var(--dbs-bridge-up); } .is-down { color: var(--dbs-bridge-down); }
  }
  .dbs-bridge-qr {
    position: relative; height: 6px; margin-top: 8px; border-radius: 3px;
    background: linear-gradient(90deg, var(--dbs-bridge-up) calc(var(--dbs-bridge-qr) * 25%), var(--dbs-bridge-line) 0);
    transition: --dbs-bridge-qr .9s var(--dbs-bridge-spring);
    i { position: absolute; top: -2px; bottom: -2px; width: 1px; background: var(--dbs-bridge-panel); }
    i:nth-child(1) { left: 25%; } i:nth-child(2) { left: 50%; } i:nth-child(3) { left: 75%; }
  }

  .dbs-bridge-chart { grid-area: chart; display: flex; flex-direction: column; min-height: 0; }
  .dbs-bridge-wfbox { position: relative; flex: 1; min-height: 220px; }
  .dbs-bridge-wf { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }

  .dbs-bridge-grid line { stroke: var(--dbs-bridge-line); }
  .dbs-bridge-grid text, .dbs-bridge-axnote { fill: var(--dbs-bridge-mute); font-size: 10.5px; font-family: var(--dbs-bridge-mono); }
  .dbs-bridge-b {
    cursor: pointer; outline: none; transition: opacity .25s var(--dbs-bridge-ease);
    .dbs-bridge-hit { fill: transparent; }
    .dbs-bridge-r { fill: var(--dbs-bridge-ink); transform-box: fill-box; transform-origin: 50% 100%; }
    .dbs-bridge-ring { fill: none; stroke: var(--dbs-bridge-ink); stroke-width: 1.5; opacity: 0; transition: opacity .2s; }
    .dbs-bridge-brk { fill: none; stroke: var(--dbs-bridge-panel); stroke-width: 3; stroke-linejoin: round; }
    .dbs-bridge-v { font-size: 11.5px; font-weight: 650; fill: var(--dbs-bridge-ink); letter-spacing: -.01em; }
    .dbs-bridge-xlab { font-size: 11px; fill: var(--dbs-bridge-mute); font-weight: 550; }
    &[data-k="new"] .dbs-bridge-r { fill: var(--dbs-bridge-up); }
    &[data-k="exp"] .dbs-bridge-r { fill: var(--dbs-bridge-up-2); }
    &[data-k="react"] .dbs-bridge-r { fill: var(--dbs-bridge-up-3); }
    &[data-k="contr"] .dbs-bridge-r { fill: var(--dbs-bridge-down-2); transform-origin: 50% 0; }
    &[data-k="churn"] .dbs-bridge-r { fill: var(--dbs-bridge-down); transform-origin: 50% 0; }
    &[data-k="end"] .dbs-bridge-r { fill: color-mix(in oklch, var(--dbs-bridge-ink) 86%, var(--dbs-bridge-up)); }
    &[data-k="new"] .dbs-bridge-v, &[data-k="exp"] .dbs-bridge-v, &[data-k="react"] .dbs-bridge-v { fill: var(--dbs-bridge-up); }
    &[data-k="contr"] .dbs-bridge-v, &[data-k="churn"] .dbs-bridge-v { fill: var(--dbs-bridge-down); }
    &:focus-visible .dbs-bridge-ring, &.is-pin .dbs-bridge-ring { opacity: 1; }
  }
  .dbs-bridge-wf.is-narrow { .dbs-bridge-v { font-size: 10px; letter-spacing: -.02em; } .dbs-bridge-xlab { font-size: 10px; } }
  .dbs-bridge-wf:has(.dbs-bridge-b:hover) .dbs-bridge-b:not(:hover), .dbs-bridge-wf[data-pin] .dbs-bridge-b:not(.is-pin):not(:hover) { opacity: .42; }
  .dbs-bridge-c { stroke: var(--dbs-bridge-line-2); stroke-dasharray: 2 3; }
  .dbs-bridge-cross { stroke: var(--dbs-bridge-ink); stroke-width: 1; stroke-dasharray: 1 3; opacity: 0; transition: opacity .15s; }
  .dbs-bridge-crossl { opacity: 0; transition: opacity .15s;
    rect { fill: var(--dbs-bridge-ink); } text { fill: var(--dbs-bridge-paper); font: 600 10.5px var(--dbs-bridge-mono); }
  }
  .dbs-bridge-wf.is-hover .dbs-bridge-cross, .dbs-bridge-wf.is-hover .dbs-bridge-crossl { opacity: 1; }
  .dbs-bridge-wf.is-enter {
    .dbs-bridge-r { animation: dbs-bridge-rise .9s var(--dbs-bridge-spring) backwards; animation-delay: calc(var(--i) * 70ms + 80ms); }
    .dbs-bridge-v, .dbs-bridge-brk { animation: dbs-bridge-fade .5s var(--dbs-bridge-ease) backwards; animation-delay: calc(var(--i) * 70ms + 420ms); }
    .dbs-bridge-c { animation: dbs-bridge-fade .5s var(--dbs-bridge-ease) backwards; animation-delay: calc(var(--i) * 70ms + 300ms); }
  }

  /* month scrubber */
  .dbs-bridge-scrub { grid-area: scrub; padding-bottom: 8px; }
  .dbs-bridge-months {
    display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); gap: 4px; padding: 8px 10px 0;
    button {
      position: relative; display: grid; grid-template-rows: 34px auto; gap: 4px; justify-items: center;
      border: 0; background: none; border-radius: 8px; padding: 4px 0 3px; cursor: pointer; color: var(--dbs-bridge-mute);
      font-size: 10.5px; font-weight: 600; letter-spacing: .02em; transition: background .2s, color .2s;
      &:hover { background: var(--dbs-bridge-faint); color: var(--dbs-bridge-ink); }
      &[aria-checked="true"] { background: var(--dbs-bridge-ink); color: var(--dbs-bridge-paper);
        b { background: var(--dbs-bridge-paper); }
      }
    }
    b {
      align-self: end; width: min(14px, 60%); height: calc(var(--h) * 100%); min-height: 2px; border-radius: 2px;
      background: var(--dbs-bridge-up); transform-origin: bottom;
      animation: dbs-bridge-rise .7s var(--dbs-bridge-spring) backwards; animation-delay: calc(var(--i) * 35ms + 200ms);
    }
    .is-neg b { background: var(--dbs-bridge-down); }
  }

  /* movers */
  .dbs-bridge-movers { grid-area: movers; display: flex; flex-direction: column; min-height: 0; }
  .dbs-bridge-clear {
    border: 0; background: var(--dbs-bridge-faint); border-radius: 6px; padding: 2px 8px; font-size: 11px; font-weight: 600; cursor: pointer;
    &:hover { background: var(--dbs-bridge-line); }
  }
  .dbs-bridge-mvsum { margin: 4px 14px 8px; font-size: 12px; color: var(--dbs-bridge-mute); text-wrap: pretty;
    b { color: var(--dbs-bridge-ink); font-weight: 650; }
  }
  .dbs-bridge-mvlist {
    list-style: none; margin: 0; padding: 0 8px 10px; overflow: auto; min-height: 0; flex: 1;
    scrollbar-width: thin; scrollbar-color: var(--dbs-bridge-line-2) transparent;
  }
  .dbs-bridge-mv {
    position: relative; display: grid; grid-template-columns: 8px minmax(0, 1fr) auto; align-items: center; gap: 4px 10px;
    padding: 7px 8px 9px; border-radius: 8px;
    transition: opacity .35s var(--dbs-bridge-ease), translate .5s var(--dbs-bridge-spring), background .2s;
    transition-delay: calc(var(--i) * 22ms), calc(var(--i) * 22ms), 0s;
    &:hover { background: var(--dbs-bridge-faint); }
    @starting-style { opacity: 0; translate: 0 8px; }
    small { display: block; color: var(--dbs-bridge-mute); font-size: 11px; font-weight: 450; overflow: hidden; text-overflow: ellipsis; }
  }
  .dbs-bridge-mvname { min-width: 0; font-weight: 560; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .dbs-bridge-mvamt { font-family: var(--dbs-bridge-mono); font-size: 12px; font-weight: 600; }
  .dbs-bridge-dot { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
  .dbs-bridge-mvbar { grid-column: 2 / 4; height: 3px; border-radius: 2px; background: var(--dbs-bridge-faint); overflow: hidden;
    &::before { content: ""; display: block; height: 100%; width: calc(var(--w) * 100%); background: var(--c); border-radius: 2px; }
  }
  [data-k="new"] { --c: var(--dbs-bridge-up); }
  [data-k="exp"] { --c: var(--dbs-bridge-up-2); }
  [data-k="react"] { --c: var(--dbs-bridge-up-3); }
  [data-k="contr"] { --c: var(--dbs-bridge-down-2); }
  [data-k="churn"] { --c: var(--dbs-bridge-down); }
  [data-k="net"] { --c: var(--dbs-bridge-ink); }
  .dbs-bridge-mv[data-k="contr"] .dbs-bridge-mvamt, .dbs-bridge-mv[data-k="churn"] .dbs-bridge-mvamt { color: var(--dbs-bridge-down); }
  .dbs-bridge-mv[data-k="new"] .dbs-bridge-mvamt, .dbs-bridge-mv[data-k="exp"] .dbs-bridge-mvamt, .dbs-bridge-mv[data-k="react"] .dbs-bridge-mvamt { color: var(--dbs-bridge-up); }

  /* ---------- trend ---------- */
  .dbs-bridge-v-trend { height: 100%; display: grid; grid-template-rows: minmax(0, 1fr) auto; gap: 12px; }
  .dbs-bridge-trendp { display: flex; flex-direction: column; min-height: 0; }
  .dbs-bridge-trbox { position: relative; flex: 1; min-height: 260px; }
  .dbs-bridge-tr { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible;
    .dbs-bridge-col rect { transform-box: fill-box; animation: dbs-bridge-rise .8s var(--dbs-bridge-spring) backwards; animation-delay: calc(var(--i) * 40ms); }
    .dbs-bridge-col .is-neg { transform-origin: 50% 0; }
    .dbs-bridge-col .is-pos { transform-origin: 50% 100%; }
    .dbs-bridge-col { cursor: pointer; }
    .dbs-bridge-col .dbs-bridge-hit { fill: transparent; animation: none; }
    .dbs-bridge-col:hover .dbs-bridge-hit, .dbs-bridge-col:focus-visible .dbs-bridge-hit { fill: var(--dbs-bridge-faint); }
    .dbs-bridge-col.is-cur .dbs-bridge-hit { fill: color-mix(in oklch, var(--dbs-bridge-ink) 7%, transparent); }
    .dbs-bridge-netl { fill: none; stroke: var(--dbs-bridge-ink); stroke-width: 1.75; stroke-linejoin: round; stroke-dasharray: 1; stroke-dashoffset: 1;
      animation: dbs-bridge-draw 1.1s var(--dbs-bridge-ease) .35s forwards; }
    .dbs-bridge-netd { fill: var(--dbs-bridge-panel); stroke: var(--dbs-bridge-ink); stroke-width: 1.75; animation: dbs-bridge-fade .4s var(--dbs-bridge-ease) backwards; animation-delay: calc(var(--i) * 60ms + .5s); }
    .dbs-bridge-xt { font-size: 10.5px; fill: var(--dbs-bridge-mute); font-weight: 600; }
    .dbs-bridge-zero { stroke: var(--dbs-bridge-line-2); }
  }
  .dbs-bridge-legend { display: flex; flex-wrap: wrap; gap: 4px 12px; list-style: none; margin: 0; padding: 0; font-size: 11px; color: var(--dbs-bridge-mute);
    li { display: flex; align-items: center; gap: 5px; }
    li::before { content: ""; width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
    li[data-k="net"]::before { height: 2px; border-radius: 1px; }
  }
  .dbs-bridge-ttm { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 12px;
    div { padding: 10px 12px; border-radius: 10px; border: 1px solid var(--dbs-bridge-line); background: var(--dbs-bridge-panel); border-top: 3px solid var(--c); }
    span { display: block; font-size: 10.5px; letter-spacing: .07em; text-transform: uppercase; font-weight: 650; color: var(--dbs-bridge-mute); }
    b { font-size: 15px; font-weight: 650; letter-spacing: -.01em; }
  }

  /* ---------- accounts table ---------- */
  .dbs-bridge-v-acc { height: 100%; }
  .dbs-bridge-tablep { height: 100%; display: flex; flex-direction: column; min-height: 0; }
  .dbs-bridge-tbar { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px; padding: 12px 14px;
    h3 { margin: 0 auto 0 0; font-size: 11px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dbs-bridge-mute); }
  }
  .dbs-bridge-chips { display: flex; flex-wrap: wrap; gap: 6px;
    button { display: inline-flex; align-items: center; gap: 6px; border: 1px solid var(--dbs-bridge-line); background: none; border-radius: 99px; padding: 3px 10px 3px 8px; font-size: 11.5px; font-weight: 560; cursor: pointer; color: var(--dbs-bridge-mute); transition: background .2s, color .2s, border-color .2s;
      &::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--c); opacity: .35; transition: opacity .2s, scale .3s var(--dbs-bridge-spring); }
      &[aria-pressed="true"] { color: var(--dbs-bridge-ink); border-color: var(--dbs-bridge-line-2); background: var(--dbs-bridge-panel); &::before { opacity: 1; scale: 1.25; } }
    }
  }
  .dbs-bridge-search { display: flex; align-items: center; gap: 6px; padding: 0 10px; height: 30px; border-radius: 8px; box-shadow: inset 0 0 0 1px var(--dbs-bridge-line); background: var(--dbs-bridge-paper);
