@keyframes dbs-health-vt-in { from { opacity: 0; filter: blur(4px); transform: scale(.985); } }
html:has(.dbs-health)::view-transition-old(dbs-health-main) { animation: 150ms cubic-bezier(.4,0,1,1) both dbs-health-vt-out; }
html:has(.dbs-health)::view-transition-new(dbs-health-main) { animation: 380ms cubic-bezier(.16,1,.3,1) 40ms both dbs-health-vt-in; }

.dbs-health *, .dbs-health *::before, .dbs-health *::after { box-sizing: border-box; }
.dbs-health {
  --dbs-health-bg: oklch(0.205 0.017 168);
  --dbs-health-fg: oklch(0.94 0.012 150);
  --dbs-health-good: oklch(0.82 0.13 166);
  --dbs-health-warn: oklch(0.84 0.13 84);
  --dbs-health-bad: oklch(0.71 0.165 29);

  --dbs-health-panel: color-mix(in oklch, var(--dbs-health-bg), var(--dbs-health-fg) 4%);
  --dbs-health-side: color-mix(in oklch, var(--dbs-health-bg), black 22%);
  --dbs-health-line: color-mix(in oklch, var(--dbs-health-fg) 10%, transparent);
  --dbs-health-line-2: color-mix(in oklch, var(--dbs-health-fg) 18%, transparent);
  --dbs-health-mute: color-mix(in oklch, var(--dbs-health-fg) 55%, var(--dbs-health-bg));
  --dbs-health-faint: color-mix(in oklch, var(--dbs-health-fg) 5%, transparent);
  --dbs-health-ease: cubic-bezier(.16, 1, .3, 1);
  --dbs-health-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  --dbs-health-mono: ui-monospace, Menlo, "SF Mono", Consolas, monospace;

  position: relative; width: 100%; height: var(--dbs-health-h, 680px); container-type: inline-size; overflow: hidden;
  border-radius: 14px; background: var(--dbs-health-bg); color: var(--dbs-health-fg);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased; color-scheme: dark; accent-color: var(--dbs-health-good);

  button, select { font: inherit; color: inherit; }
  :focus-visible { outline: 2px solid var(--dbs-health-good); outline-offset: 2px; }
  svg { display: block; }
  [data-band="good"] { --c: var(--dbs-health-good); }
  [data-band="warn"] { --c: var(--dbs-health-warn); }
  [data-band="bad"] { --c: var(--dbs-health-bad); }

  .dbs-health-app { height: 100%; display: grid; grid-template-columns: 196px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side head" "side main"; }

  .dbs-health-side { grid-area: side; display: flex; flex-direction: column; gap: 24px; padding: 18px 12px; background: var(--dbs-health-side); border-right: 1px solid var(--dbs-health-line); }
  .dbs-health-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px;
    svg { width: 30px; height: 30px; padding: 6px; flex: none; border-radius: 50%; background: var(--dbs-health-good); stroke: var(--dbs-health-bg); fill: none; stroke-width: 1.8; stroke-linecap: round; }
    b { display: block; font-weight: 680; letter-spacing: -.01em; }
    small { display: block; font-size: 11px; color: var(--dbs-health-mute); }
  }
  .dbs-health-nav { display: grid; gap: 3px;
    button { position: relative; display: flex; align-items: center; gap: 10px; height: 36px; padding: 0 10px; border: 0; border-radius: 8px; background: none; color: var(--dbs-health-mute); cursor: pointer; text-align: left; font-weight: 550; transition: color .2s, background .2s;
      svg { width: 16px; height: 16px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
      &:hover { color: var(--dbs-health-fg); background: var(--dbs-health-faint); }
      &[aria-selected="true"] { color: var(--dbs-health-fg); background: color-mix(in oklch, var(--dbs-health-good) 12%, transparent);
        &::before { content: ""; position: absolute; left: -12px; top: 9px; bottom: 9px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dbs-health-good); }
      }
    }
  }
  .dbs-health-badge { margin-left: auto; font-style: normal; font: 600 10.5px var(--dbs-health-mono); padding: 1px 6px; border-radius: 99px; background: color-mix(in oklch, var(--dbs-health-bad) 22%, transparent); color: var(--dbs-health-bad); }
  .dbs-health-me { margin-top: auto; display: flex; gap: 10px; align-items: center; padding: 0 6px;
    i { width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center; font: 650 10.5px system-ui; font-style: normal; background: color-mix(in oklch, var(--dbs-health-warn) 22%, var(--dbs-health-bg)); color: var(--dbs-health-warn); flex: none; }
    b { display: block; font-size: 12px; font-weight: 600; } small { display: block; font-size: 11px; color: var(--dbs-health-mute); }
  }

  .dbs-health-head { grid-area: head; display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 12px 18px; padding: 18px 20px 12px; }
  .dbs-health-title h2 { margin: 0; font-size: clamp(19px, 2.1cqi, 25px); font-weight: 650; letter-spacing: -.02em; line-height: 1.1; text-wrap: balance; }
  .dbs-health-sub { margin: 4px 0 0; color: var(--dbs-health-mute); text-wrap: pretty; }
  .dbs-health-filters { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
  .dbs-health-segs { display: flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--dbs-health-faint); box-shadow: inset 0 0 0 1px var(--dbs-health-line);
    button { border: 0; background: none; padding: 4px 10px; border-radius: 6px; font-weight: 550; color: var(--dbs-health-mute); cursor: pointer; white-space: nowrap; transition: background .2s, color .2s;
      &[aria-checked="true"] { background: var(--dbs-health-fg); color: var(--dbs-health-bg); }
      &:hover:not([aria-checked="true"]) { color: var(--dbs-health-fg); }
    }
  }
  .dbs-health-sel { display: flex; align-items: center; gap: 6px; height: 32px; padding: 0 4px 0 10px; border-radius: 9px; box-shadow: inset 0 0 0 1px var(--dbs-health-line); font-size: 12px; color: var(--dbs-health-mute);
    select { border: 0; background: transparent; padding: 4px 2px; font-weight: 550; color: var(--dbs-health-fg); cursor: pointer; outline: none; }
    &:focus-within { box-shadow: inset 0 0 0 1.5px var(--dbs-health-good); }
  }
  .dbs-health-chk { display: flex; align-items: center; gap: 7px; height: 32px; padding: 0 10px; border-radius: 9px; box-shadow: inset 0 0 0 1px var(--dbs-health-line); font-size: 12px; font-weight: 550; cursor: pointer;
    input { width: 14px; height: 14px; margin: 0; }
    &:has(input:checked) { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbs-health-good) 60%, transparent); background: color-mix(in oklch, var(--dbs-health-good) 9%, transparent); }
  }

  .dbs-health-main { grid-area: main; min-height: 0; overflow: auto; padding: 0 20px 18px; scrollbar-width: thin; scrollbar-color: var(--dbs-health-line-2) transparent; }
  .dbs-health-view[hidden] { display: none !important; }
  .dbs-health-panel { background: var(--dbs-health-panel); border: 1px solid var(--dbs-health-line); border-radius: 12px; min-width: 0; }
  .dbs-health-ph { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; flex-wrap: wrap; padding: 12px 14px 0;
    h3 { margin: 0; font-size: 11px; letter-spacing: .09em; text-transform: uppercase; color: var(--dbs-health-mute); font-weight: 650; }
  }
  .dbs-health-hint, .dbs-health-count, .dbs-health-rensum { margin: 0; font-size: 11.5px; color: var(--dbs-health-mute); }

  .dbs-health-v-port { height: 100%; display: grid; gap: 12px; grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "kpi kpi" "plot table"; }
  .dbs-health-kpis { grid-area: kpi; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
  .dbs-health-kpi { padding: 11px 14px; border-radius: 12px; border: 1px solid var(--dbs-health-line); background: var(--dbs-health-panel); animation: dbs-health-in .6s var(--dbs-health-ease) backwards; animation-delay: calc(var(--i) * 60ms);
    h4 { margin: 0; font-size: 10.5px; letter-spacing: .09em; text-transform: uppercase; color: var(--dbs-health-mute); font-weight: 650; }
    p { margin: 4px 0 0; font-size: clamp(19px, 2.2cqi, 26px); font-weight: 620; letter-spacing: -.02em; line-height: 1.1; }
    small { display: block; margin-top: 3px; font-size: 11.5px; color: var(--dbs-health-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    &.is-bad p { color: var(--dbs-health-bad); }
  }

  .dbs-health-plotp { grid-area: plot; display: flex; flex-direction: column; min-height: 0; }
  .dbs-health-plotbox { position: relative; flex: 1; min-height: 240px; }
  .dbs-health-plot { position: absolute; inset: 0; width: 100%; height: 100%; touch-action: none; cursor: crosshair; user-select: none; -webkit-user-select: none; }
  .dbs-health-q { fill: none; }
  .dbs-health-qlab { font-size: 10px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; fill: var(--dbs-health-mute); opacity: .7; }
  .dbs-health-grid line { stroke: var(--dbs-health-line); }
  .dbs-health-grid text { font: 10.5px var(--dbs-health-mono); fill: var(--dbs-health-mute); }
  .dbs-health-axl { font-size: 10.5px; fill: var(--dbs-health-mute); font-weight: 550; }
  .dbs-health-mid { stroke: var(--dbs-health-line-2); stroke-dasharray: 3 4; }
  .dbs-health-zone { fill: color-mix(in oklch, var(--dbs-health-bad) 7%, transparent); }
  .dbs-health-dot {
    cursor: pointer; transform-box: fill-box; transform-origin: center;
    transition: opacity .35s var(--dbs-health-ease), filter .35s, transform .45s var(--dbs-health-spring);
    animation: dbs-health-pop .7s var(--dbs-health-spring) backwards; animation-delay: calc(var(--i) * 14ms + 150ms);
    circle { fill: color-mix(in oklch, var(--c) 30%, transparent); stroke: var(--c); stroke-width: 1.5; }
    .dbs-health-flagring { fill: none; stroke: var(--dbs-health-bad); stroke-width: 1; stroke-dasharray: 2 2; animation: dbs-health-pulse 2.4s ease-in-out infinite; }
    &:hover, &.is-hot { transform: scale(1.25); circle { fill: color-mix(in oklch, var(--c) 60%, transparent); } }
    &.is-out { opacity: .16; filter: saturate(0); }
    &.is-gone { opacity: 0; transform: scale(.2); pointer-events: none; }
    &.is-open circle { stroke-width: 2.5; fill: var(--c); }
  }
  .dbs-health-plot.is-off .dbs-health-flagring { animation-play-state: paused; }
  .dbs-health-brush { fill: color-mix(in oklch, var(--dbs-health-good) 12%, transparent); stroke: var(--dbs-health-good); stroke-width: 1; stroke-dasharray: 4 3; }
  .dbs-health-lens { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 14px; min-height: 38px; padding: 8px 14px; border-top: 1px solid var(--dbs-health-line); font-size: 12px; color: var(--dbs-health-mute);
    b { color: var(--dbs-health-fg); font-weight: 620; }
    button { margin-left: auto; border: 0; border-radius: 6px; padding: 3px 9px; background: var(--dbs-health-faint); font-size: 11.5px; font-weight: 600; cursor: pointer; &:hover { background: var(--dbs-health-line-2); } }
  }

  .dbs-health-tablep { grid-area: table; display: flex; flex-direction: column; min-height: 0; }
  .dbs-health-tscroll { flex: 1; min-height: 0; overflow: auto; margin-top: 8px; border-top: 1px solid var(--dbs-health-line); scrollbar-width: thin; scrollbar-color: var(--dbs-health-line-2) transparent; }
  .dbs-health-table { width: 100%; border-collapse: collapse; table-layout: fixed;
    th:nth-child(2), th:nth-child(3) { width: 64px; } th:nth-child(4) { width: 76px; } th:nth-child(5) { width: 66px; }
    td:first-child { overflow: hidden; text-overflow: ellipsis; }
    .dbs-health-nm { overflow: hidden; } .dbs-health-nm > span { overflow: hidden; text-overflow: ellipsis; }
    th { position: sticky; top: 0; z-index: 1; background: var(--dbs-health-panel); padding: 7px 10px; text-align: left; font-size: 10.5px; letter-spacing: .08em; text-transform: uppercase; font-weight: 650; color: var(--dbs-health-mute); border-bottom: 1px solid var(--dbs-health-line); white-space: nowrap;
      button { border: 0; background: none; padding: 0; font: inherit; letter-spacing: inherit; text-transform: inherit; color: inherit; cursor: pointer; }
      &[aria-sort="ascending"] button::after { content: " \2191"; }
      &[aria-sort="descending"] button::after { content: " \2193"; }
      &:not([aria-sort="none"]) { color: var(--dbs-health-fg); }
    }
    td { padding: 7px 10px; border-bottom: 1px solid var(--dbs-health-line); white-space: nowrap; }
    tbody tr { cursor: pointer; outline: none; transition: background .15s;
      &:hover, &.is-hot { background: var(--dbs-health-faint); }
      &:focus-visible { background: color-mix(in oklch, var(--dbs-health-good) 10%, transparent); box-shadow: inset 2px 0 0 var(--dbs-health-good); }
      &[aria-current="true"] { background: color-mix(in oklch, var(--dbs-health-good) 14%, transparent); }
    }
    small { display: block; color: var(--dbs-health-mute); font-size: 11px; overflow: hidden; text-overflow: ellipsis; }
  }
  .dbs-health-n { text-align: right !important; font-family: var(--dbs-health-mono); font-size: 12px; }
  .dbs-health-nm { font-weight: 560; display: flex; align-items: center; gap: 6px; }
  .dbs-health-fl { width: 6px; height: 6px; border-radius: 50%; background: var(--dbs-health-bad); flex: none; }
  .dbs-health-planb { font: 600 9.5px var(--dbs-health-mono); padding: 1px 5px; border-radius: 4px; background: color-mix(in oklch, var(--dbs-health-good) 18%, transparent); color: var(--dbs-health-good); letter-spacing: .04em; }
  .dbs-health-sc { display: inline-flex; align-items: center; gap: 6px; color: var(--c); font-weight: 650;
    &::before { content: ""; width: 9px; height: 9px; border-radius: 50%; background: conic-gradient(var(--c) calc(var(--v) * 1%), color-mix(in oklch, var(--c) 18%, transparent) 0); }
  }
  .dbs-health-up { color: var(--dbs-health-good); } .dbs-health-down { color: var(--dbs-health-bad); }
  @supports (animation-timeline: view()) {
    .dbs-health-table tbody tr, .dbs-health-renlist li { animation: dbs-health-in linear both; animation-timeline: view(); animation-range: entry 0% entry 85%; }
  }

  /* flags view */
  .dbs-health-flaggrid { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 250px), 1fr)); gap: 12px; }
  .dbs-health-fcard { position: relative; display: flex; flex-direction: column; gap: 8px; padding: 14px; border-radius: 12px; border: 1px solid var(--dbs-health-line); background: var(--dbs-health-panel); cursor: pointer; text-align: left;
    transition: border-color .25s, translate .45s var(--dbs-health-spring), box-shadow .3s;
    animation: dbs-health-in .55s var(--dbs-health-ease) backwards; animation-delay: calc(var(--i) * 55ms);
    &:hover { border-color: color-mix(in oklch, var(--dbs-health-bad) 50%, transparent); translate: 0 -2px; box-shadow: 0 14px 30px -18px color-mix(in oklch, var(--dbs-health-bad) 60%, transparent); }
    h4 { margin: 0; font-size: 14px; font-weight: 620; }
    p { margin: 0; font-size: 12px; color: var(--dbs-health-mute); text-wrap: pretty; }
    .dbs-health-fnum { display: flex; align-items: baseline; gap: 10px; b { font-size: 28px; font-weight: 600; letter-spacing: -.03em; line-height: 1; } span { color: var(--dbs-health-mute); font-size: 12px; } }
    .dbs-health-fbar { height: 4px; border-radius: 2px; background: var(--dbs-health-faint); overflow: hidden; &::before { content: ""; display: block; height: 100%; width: calc(var(--w) * 100%); background: var(--dbs-health-bad); border-radius: 2px; } }
    ul { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 4px; }
    li { font-size: 11px; padding: 2px 7px; border-radius: 99px; background: var(--dbs-health-faint); color: var(--dbs-health-fg); }
    .dbs-health-go { margin-top: auto; font-size: 11.5px; font-weight: 600; color: var(--dbs-health-good); }
  }

  /* renewals */
  .dbs-health-v-ren { height: 100%; display: grid; gap: 12px; grid-template-columns: minmax(0, 1.6fr) minmax(0, 1fr); }
  .dbs-health-renp, .dbs-health-renlistp { display: flex; flex-direction: column; min-height: 0; }
  .dbs-health-renbox { position: relative; flex: 1; min-height: 260px; }
  .dbs-health-ren { position: absolute; inset: 0; width: 100%; height: 100%;
    .dbs-health-rd { cursor: pointer; transform-box: fill-box; transform-origin: center; animation: dbs-health-pop .6s var(--dbs-health-spring) backwards; animation-delay: calc(var(--i) * 18ms);
      fill: color-mix(in oklch, var(--c) 35%, transparent); stroke: var(--c); stroke-width: 1.5; transition: transform .3s var(--dbs-health-spring);
      &:hover { transform: scale(1.2); }
    }
    .dbs-health-today { stroke: var(--dbs-health-good); stroke-width: 1.5; }
    .dbs-health-todayl { fill: var(--dbs-health-good); font: 600 10px var(--dbs-health-mono); }
    .dbs-health-win { fill: color-mix(in oklch, var(--dbs-health-fg) 2.5%, transparent); }
    .dbs-health-danger { fill: color-mix(in oklch, var(--dbs-health-bad) 10%, transparent); stroke: color-mix(in oklch, var(--dbs-health-bad) 35%, transparent); stroke-dasharray: 3 3; }
    .dbs-health-dangerl { fill: var(--dbs-health-bad); font: 650 9.5px system-ui; letter-spacing: .1em; opacity: .8; }
    .dbs-health-rdl { fill: var(--dbs-health-fg); font-size: 11px; font-weight: 550; pointer-events: none; animation: dbs-health-in .5s var(--dbs-health-ease) .5s backwards; }
  }
  .dbs-health-key { display: flex; gap: 12px; list-style: none; margin: 0; padding: 0; font-size: 11px; color: var(--dbs-health-mute);
    li { display: flex; align-items: center; gap: 5px; } li::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
  }
  .dbs-health-renlist { list-style: none; margin: 8px 0 0; padding: 0 8px 8px; overflow: auto; flex: 1; min-height: 0; scrollbar-width: thin; scrollbar-color: var(--dbs-health-line-2) transparent;
    li { display: grid; grid-template-columns: 44px minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 7px 6px; border-radius: 8px; cursor: pointer; &:hover { background: var(--dbs-health-faint); } }
    time { font: 600 11px var(--dbs-health-mono); color: var(--dbs-health-mute); text-align: center; line-height: 1.15; b { display: block; font-size: 15px; color: var(--dbs-health-fg); } }
    small { display: block; color: var(--dbs-health-mute); font-size: 11px; }
  }

  /* drawer */
  .dbs-health-scrim { position: absolute; inset: 0; z-index: 30; background: color-mix(in oklch, var(--dbs-health-bg), black 40%); opacity: 0; pointer-events: none; transition: opacity .35s; }
  &:has(.dbs-health-drawer.is-open) .dbs-health-scrim { opacity: .55; pointer-events: auto; }
  .dbs-health-drawer {
    position: absolute; z-index: 31; top: 10px; right: 10px; bottom: 10px; width: min(380px, calc(100% - 20px));
    display: none; flex-direction: column; border-radius: 14px; border: 1px solid var(--dbs-health-line-2);
    background: color-mix(in oklch, var(--dbs-health-bg), var(--dbs-health-fg) 6%);
    box-shadow: 0 30px 60px -20px black;
    translate: calc(100% + 20px) 0; opacity: 0;
    transition: translate .55s var(--dbs-health-spring), opacity .3s, display .55s allow-discrete;
    &.is-open { display: flex; translate: 0 0; opacity: 1; }
    h4 { margin: 18px 0 8px; font-size: 10.5px; letter-spacing: .09em; text-transform: uppercase; color: var(--dbs-health-mute); font-weight: 650; }
  }
  @starting-style { .dbs-health-drawer.is-open { translate: calc(100% + 20px) 0; opacity: 0; } }
  .dbs-health-dh { display: flex; justify-content: space-between; gap: 10px; padding: 16px 16px 12px; border-bottom: 1px solid var(--dbs-health-line);
    h3 { margin: 2px 0 0; font-size: 18px; font-weight: 650; letter-spacing: -.015em; text-wrap: balance; }
  }
  .dbs-health-dseg { margin: 0; font-size: 11px; color: var(--dbs-health-mute); letter-spacing: .04em; }
  .dbs-health-x { width: 30px; height: 30px; flex: none; display: grid; place-items: center; border: 0; border-radius: 8px; background: var(--dbs-health-faint); cursor: pointer;
    svg { width: 14px; height: 14px; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; } &:hover { background: var(--dbs-health-line-2); } }
  .dbs-health-dbody { flex: 1; overflow: auto; padding: 4px 16px 16px; scrollbar-width: thin; scrollbar-color: var(--dbs-health-line-2) transparent; }
  .dbs-health-dtop { display: flex; gap: 16px; align-items: center; margin-top: 14px; }
  .dbs-health-ring { position: relative; width: 92px; height: 92px; flex: none; border-radius: 50%; display: grid; place-content: center; text-align: center;
    background: conic-gradient(var(--c) var(--dbs-health-p), color-mix(in oklch, var(--c) 14%, transparent) 0);
    transition: --dbs-health-p 1.1s var(--dbs-health-ease);
    &::before { content: ""; position: absolute; inset: 7px; border-radius: 50%; background: color-mix(in oklch, var(--dbs-health-bg), var(--dbs-health-fg) 6%); }
    b, small { position: relative; }
    b { font-size: 28px; font-weight: 640; letter-spacing: -.03em; line-height: 1; color: var(--c); }
    small { font-size: 10px; letter-spacing: .1em; text-transform: uppercase; color: var(--dbs-health-mute); }
  }
