tbody.addEventListener('click', e => { const tr = e.target.closest('tr[data-id]'); if (tr) openDrawer(tr.dataset.id); });
tbody.addEventListener('keydown', e => {
  const tr = e.target.closest('tr[data-id]'); if (!tr) return;
