tbody.addEventListener('focusin', e => { const tr = e.target.closest('tr[data-id]'); if (tr) setHot(tr.dataset.id); });

/* ---------------- flags view ---------------- */
function renderFlags() {
  const v = visible(), tot = v.reduce((s, a) => s + a.arr, 0) || 1;
