      '<div class="dbs-health-fnum"><b>' + list.length + '</b><span>accounts · ' + kfmt(arr) + ' ARR · ' + (arr / tot * 100).toFixed(1) + '%</span></div><i class="dbs-health-fbar"></i>' +
      '<ul>' + list.slice(0, 4).map(a => '<li>' + a.name + '</li>').join('') + (list.length > 4 ? '<li>+' + (list.length - 4) + ' more</li>' : '') + '</ul>' +
