/* ---------------- renewals view ---------------- */
function renderRenewals() {
  const svg = $('.dbs-health-ren'), box = svg.parentNode, W = box.clientWidth, H = box.clientHeight;
  const v = visible().filter(a => a.renewal <= 180).sort((a, b) => a.renewal - b.renewal);
