    mk('rect', { class: 'dbs-health-danger', x: x(0), y: yv(60), width: x(60) - x(0), height: yv(0) - yv(60), rx: 4 }, svg);
    mk('text', { class: 'dbs-health-dangerl', x: x(0) + 8, y: yv(0) - 8 }, svg).textContent = 'RENEWAL RISK ZONE';
    mk('line', { class: 'dbs-health-today', x1: x(0), x2: x(0), y1: mt - 6, y2: mt + ih }, svg);
    mk('text', { class: 'dbs-health-todayl', x: x(0) + 5, y: mt - 2 }, svg).textContent = 'TODAY · OCT 2';
    const labs = [];
    v.forEach((a, i) => {
