      const c = mk('circle', { class: 'dbs-health-rd', 'data-id': a.id, 'data-band': band(a.score), cx, cy, r: R, style: '--i:' + i }, svg);
      c.addEventListener('pointerenter', e => placeTip(accTip(a), e.clientX, e.clientY));
      c.addEventListener('pointerleave', hideTip);
