    labs.sort((p, q) => p.y - q.y).forEach((l, k) => {
      const prev = labs.slice(0, k).filter(o => Math.abs(o.x - l.x) < 130);
      prev.forEach(o => { if (l.y - o.y < 13) l.y = o.y + 13; });
      mk('text', { class: 'dbs-health-rdl', x: l.x, y: l.y }, svg).textContent = l.t;
    });
  }
  const n90 = v.filter(a => a.renewal <= 90), arr = n90.reduce((s, a) => s + a.arr, 0);
  $('.dbs-health-rensum').textContent = n90.length + ' renewals · ' + kfmt(arr) + ' ARR';
  $('.dbs-health-renlist').innerHTML = n90.map(a => { const d = dateIn(a.renewal); return '<li data-id="' + a.id + '" tabindex="0"><time><b>' + d.getDate() + '</b>' + d.toLocaleDateString('en-US', { month: 'short' }) + '</time><span>' + a.name + '<small>' + kfmt(a.arr) + ' · ' + a.csm + '</small></span><span class="dbs-health-sc" data-band="' + band(a.score) + '" style="--v:' + a.score + '">' + a.score + '</span></li>'; }).join('') || '<li>No renewals in the next 90 days.</li>';
}
$('.dbs-health-renlist').addEventListener('click', e => { const li = e.target.closest('li[data-id]'); if (li) openDrawer(li.dataset.id); });
$('.dbs-health-renlist').addEventListener('keydown', e => { const li = e.target.closest('li[data-id]'); if (li && e.key === 'Enter') openDrawer(li.dataset.id); });

/* ---------------- drawer ---------------- */
const drawer = $('.dbs-health-drawer');
let lastFocus = null;
function openDrawer(id) {
