  st.open = id;
  const b = band(a.score);
  drawer.setAttribute('data-band', b);
  $('.dbs-health-dseg').textContent = SEGL[a.seg].toUpperCase() + ' · ' + a.csm;
  $('.dbs-health-dname').textContent = a.name;
  $('.dbs-health-rv').textContent = a.score;
  const ring = $('.dbs-health-ring');
