  $('.dbs-health-facts').innerHTML = '<dt>ARR</dt><dd>' + usd.format(a.arr) + '</dd><dt>Renews</dt><dd>' + fmtDate(dateIn(a.renewal)) + '</dd><dt>WAU 30d</dt><dd>' + (a.trend > 0 ? '+' : '') + a.trend + '%</dd><dt>NPS</dt><dd>' + a.nps + ' / 10</dd><dt>Status</dt><dd style="color:var(--c)">' + bandLabel[b] + '</dd>';
  $('.dbs-health-factors').innerHTML = FACT.map((f, i) => '<li data-band="' + band(a.f[f.k]) + '" style="--v:' + a.f[f.k] + ';--i:' + i + '"><span>' + f.label + ' · ' + a.f[f.k] + ' × ' + Math.round(f.w * 100) + '%</span><b>' + (a.f[f.k] * f.w).toFixed(1) + '</b><i></i></li>').join('') +
    '<li class="dbs-health-tot"><span>Weighted score</span><b>' + a.raw.toFixed(1) + ' → ' + a.score + '</b></li>';
  $('.dbs-health-dflags').innerHTML = a.flags.length ? a.flags.map(f => '<li><b>' + f.label + '</b><span>' + f.why(a) + '</span></li>').join('') : '<li class="dbs-health-none"><b>No open flags</b><span>Nothing needs attention this week.</span></li>';
  const plan = $('.dbs-health-plan');
  plan.setAttribute('aria-pressed', a.plan); plan.textContent = a.plan ? 'Success plan open ✓' : 'Open success plan';
  drawer.setAttribute('aria-label', a.name + ' health detail');
  drawer.classList.add('is-open');
  drawSpark(a);
  requestAnimationFrame(() => { if (!root.isConnected) return; requestAnimationFrame(() => { if (!root.isConnected) return; ring.style.setProperty('--dbs-health-p', (a.score * 3.6) + 'deg'); }); });
  drawer.focus({ preventScroll: true });
