  if (lastFocus && root.contains(lastFocus)) lastFocus.focus({ preventScroll: true });
}
function drawSpark(a) {
  const svg = $('.dbs-health-spark'), W = svg.parentNode.clientWidth || 340, H = 84, pad = 4;
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H); svg.textContent = '';
  const x = i => pad + i / 11 * (W - pad * 2), y = v => 6 + (1 - v / 100) * (H - 12);
  mk('line', { class: 'dbs-health-s60', x1: 0, x2: W, y1: y(60), y2: y(60) }, svg);
