  mk('path', { class: 'dbs-health-sl', pathLength: 1, d: 'M' + pts.join('L') }, svg);
  const cx = mk('line', { class: 'dbs-health-sx', y1: 0, y2: H }, svg), cd = mk('circle', { class: 'dbs-health-sd', r: 3.5 }, svg);
  const sp = $('.dbs-health-sptip');
  svg.onpointermove = e => {
    const rr = svg.getBoundingClientRect(), i = clamp(Math.round((e.clientX - rr.left - pad) / (W - pad * 2) * 11), 0, 11);
    cx.setAttribute('x1', x(i)); cx.setAttribute('x2', x(i)); cd.setAttribute('cx', x(i)); cd.setAttribute('cy', y(a.hist[i]));
    const d = new Date(TODAY); d.setDate(d.getDate() - (11 - i) * 7);
    sp.textContent = 'Wk of ' + d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) + ' · ' + a.hist[i];
    sp.style.transform = 'translateX(' + clamp(x(i) - 50, 0, W - 120) + 'px)';
    svg.classList.add('is-hover');
  };
  svg.onpointerleave = () => svg.classList.remove('is-hover');
}
$('.dbs-health-x').addEventListener('click', closeDrawer);
$('.dbs-health-dclose').addEventListener('click', closeDrawer);
$('.dbs-health-scrim').addEventListener('click', closeDrawer);
$('.dbs-health-plan').addEventListener('click', e => {
  const a = ACC.find(x => x.id === st.open); if (!a) return;
  a.plan = !a.plan;
  e.currentTarget.setAttribute('aria-pressed', a.plan);
  e.currentTarget.textContent = a.plan ? 'Success plan open ✓' : 'Open success plan';
  renderTable();
});
drawer.addEventListener('keydown', e => {
  if (e.key !== 'Tab') return;
  const f = qa('.dbs-health-drawer button'); if (!f.length) return;
  if (e.shiftKey && document.activeElement === f[0]) { e.preventDefault(); f[f.length - 1].focus(); }
  else if (!e.shiftKey && document.activeElement === f[f.length - 1]) { e.preventDefault(); f[0].focus(); }
});

/* ---------------- views + filters ---------------- */
function render() { renderKpis(); syncPlot(); renderTable(); if (st.view === 'flags') renderFlags(); if (st.view === 'renewals') renderRenewals(); }
function switchView(v) {
  if (v === st.view) return;
  const apply = () => {
    st.view = v;
    qa('.dbs-health-nav [role="tab"]').forEach(b => { const on = b.dataset.view === v; b.setAttribute('aria-selected', on); b.tabIndex = on ? 0 : -1; });
    qa('.dbs-health-view').forEach(s => { s.hidden = s.dataset.view !== v; });
