  render();
}
root.addEventListener('click', e => {
  const t = e.target;
  const tab = t.closest('.dbs-health-nav [role="tab"]'); if (tab) { switchView(tab.dataset.view); return; }
  const sg = t.closest('.dbs-health-segs [role="radio"]'); if (sg) { setSeg(sg.dataset.seg); return; }
  if (t.closest('[data-clear]')) { st.brush = null; syncPlot(); renderTable(); return; }
  if (t.closest('[data-unflag]')) { st.flag = null; updateFlagChip(); render(); return; }
  const card = t.closest('.dbs-health-fcard'); if (card) { st.flag = card.dataset.flag; st.brush = null; updateFlagChip(); switchView('portfolio'); render(); return; }
  const srt = t.closest('[data-sort]'); if (srt) { const k = srt.dataset.sort; st.sort = { key: k, dir: st.sort.key === k ? -st.sort.dir : (k === 'name' || k === 'score' || k === 'renewal' ? 1 : -1) }; renderTable(); }
});
function updateFlagChip() {
  let chip = root.querySelector('[data-unflag]');
  if (!st.flag) { if (chip) chip.remove(); return; }
  if (!chip) { chip = document.createElement('button'); chip.setAttribute('data-unflag', ''); chip.className = 'dbs-health-chk'; $('.dbs-health-filters').appendChild(chip); }
  chip.innerHTML = 'Flag: ' + FLAGS.find(f => f.k === st.flag).label + ' <span aria-hidden="true">×</span>';
  chip.setAttribute('aria-label', 'Remove flag filter ' + FLAGS.find(f => f.k === st.flag).label);
