root.addEventListener('keydown', e => {
  if (e.key === 'Escape') { if (st.open) { e.stopPropagation(); closeDrawer(); } else if (st.brush) { st.brush = null; syncPlot(); renderTable(); } hideTip(); return; }
  if (e.target.closest('.dbs-health-segs') && (e.key === 'ArrowRight' || e.key === 'ArrowLeft')) {
    const b = qa('.dbs-health-segs [role="radio"]'), i = b.findIndex(x => x.dataset.seg === st.seg), j = (i + (e.key === 'ArrowRight' ? 1 : b.length - 1)) % b.length;
    e.preventDefault(); setSeg(b[j].dataset.seg); b[j].focus();
  }
  if (e.target.closest('.dbs-health-nav') && /Arrow/.test(e.key)) {
    const tabs = qa('.dbs-health-nav [role="tab"]'), i = tabs.indexOf(document.activeElement), j = (i + (/Down|Right/.test(e.key) ? 1 : tabs.length - 1)) % tabs.length;
    e.preventDefault(); tabs[j].focus(); switchView(tabs[j].dataset.view);
  }
