io.observe(root);

renderKpis();
measurePlot();
renderTable();

css:
@property --dbs-seats-pct { syntax: "<integer>"; inherits: true; initial-value: 0; }
@keyframes dbs-seats-up { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbs-seats-grow { from { transform: scaleY(0); } }
@keyframes dbs-seats-vt-out { to { opacity: 0; transform: scale(.99); } }
@keyframes dbs-seats-vt-in { from { opacity: 0; transform: translateY(12px); } }
html:has(.dbs-seats)::view-transition-old(dbs-seats-main) { animation: 140ms ease-in both dbs-seats-vt-out; }
html:has(.dbs-seats)::view-transition-new(dbs-seats-main) { animation: 420ms cubic-bezier(.22,1,.36,1) both dbs-seats-vt-in; }

.dbs-seats *, .dbs-seats *::before, .dbs-seats *::after { box-sizing: border-box; }
.dbs-seats {
  --dbs-seats-bg: oklch(0.974 0.005 230);
  --dbs-seats-ink: oklch(0.26 0.028 232);
  --dbs-seats-hi: oklch(0.47 0.085 196);
  --dbs-seats-lo: oklch(0.73 0.125 50);

  --dbs-seats-mid: color-mix(in oklch, var(--dbs-seats-lo) 22%, oklch(0.93 0.03 95));
  --dbs-seats-card: color-mix(in oklch, var(--dbs-seats-bg), white 70%);
  --dbs-seats-line: color-mix(in oklch, var(--dbs-seats-ink) 10%, transparent);
  --dbs-seats-line-2: color-mix(in oklch, var(--dbs-seats-ink) 20%, transparent);
  --dbs-seats-mute: color-mix(in oklch, var(--dbs-seats-ink) 55%, var(--dbs-seats-bg));
  --dbs-seats-faint: color-mix(in oklch, var(--dbs-seats-ink) 4.5%, transparent);
  --dbs-seats-ease: cubic-bezier(.22, 1, .36, 1);
  --dbs-seats-spring: linear(0, .008, .031 2.6%, .126 5.6%, .553 16.3%, .735 21.5%, .862 26.8%, .945 32.4%, .991 38.4%, 1.012 44.9%, 1.016 52.3%, 1.006 66.7%, 1);
  --dbs-seats-mono: ui-monospace, Menlo, "SF Mono", Consolas, monospace;

  position: relative; width: 100%; height: var(--dbs-seats-h, 680px); container-type: inline-size; overflow: hidden;
  border-radius: 14px; border: 1px solid var(--dbs-seats-line); background: var(--dbs-seats-bg); color: var(--dbs-seats-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased; accent-color: var(--dbs-seats-hi);

  button { font: inherit; color: inherit; }
  :focus-visible { outline: 2px solid var(--dbs-seats-ink); outline-offset: 2px; }
  svg { display: block; }

  .dbs-seats-app { height: 100%; display: grid; grid-template-rows: auto minmax(0, 1fr); }
  .dbs-seats-top { display: flex; align-items: center; gap: 20px; padding: 12px 18px; border-bottom: 1px solid var(--dbs-seats-line); background: var(--dbs-seats-card); }
  .dbs-seats-brand { display: flex; align-items: center; gap: 10px;
    svg { width: 28px; height: 28px; padding: 5px; border-radius: 8px; background: var(--dbs-seats-hi); fill: color-mix(in oklch, white 30%, transparent); stroke: white; stroke-width: 1.3; flex: none; }
    b { display: block; font-weight: 700; letter-spacing: -.01em; line-height: 1.1; } small { display: block; font-size: 11px; color: var(--dbs-seats-mute); }
  }
  .dbs-seats-tabs { display: flex; gap: 2px; margin-left: 10px;
