  $('.dbs-cohort-stats').innerHTML = [['Month 3', m3], ['Month 6', m6], ['Month 11', m11]].map(([l, v]) => '<div><span>' + l + ' · avg</span><b>' + (v * 100).toFixed(1) + '%</b></div>').join('');
}

/* ---------------- milestones ---------------- */
function drawMiles() {
  const svg = $('.dbs-cohort-miles'), box = svg.parentNode, W = box.clientWidth, H = box.clientHeight;
  if (!W || !H) return;
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H); svg.textContent = '';
  const S = series(st.plan), M = METRIC[st.metric], MS = [3, 6, 9, 11];
  const all = []; COH.forEach((_, i) => MS.forEach(m => { const v = val(S, i, m); if (v) all.push(v.ratio); })); all.push(M.bench);
  const lo = Math.floor(Math.min(...all) * 20) / 20 - .02, hi = Math.ceil(Math.max(...all) * 20) / 20 + .02;
  const ml = W < 420 ? 74 : 120, mr = 18, mt = 16, mb = 28, iw = W - ml - mr, ih = H - mt - mb, rh = ih / 12;
  const x = v => ml + (v - lo) / (hi - lo) * iw;
  const g = mk('g', { class: 'dbs-cohort-gl' }, svg);
  for (let v = Math.ceil(lo * 20) / 20; v <= hi + 1e-9; v += 0.05) { mk('line', { x1: x(v), x2: x(v), y1: mt, y2: mt + ih }, g); mk('text', { x: x(v), y: H - 8, 'text-anchor': 'middle' }, g).textContent = Math.round(v * 100) + '%'; }
  mk('line', { class: 'dbs-cohort-bench', x1: x(M.bench), x2: x(M.bench), y1: mt - 4, y2: mt + ih }, svg);
  COH.forEach((c, i) => {
    const cy = mt + rh * i + rh / 2, gg = mk('g', { class: 'dbs-cohort-mrow', style: '--i:' + i }, svg);
    mk('text', { x: 8, y: cy + 4 }, gg).textContent = W < 420 ? c.short : c.label;
    const pts = MS.map(m => [m, val(S, i, m)]).filter(p => p[1]);
    if (!pts.length) { mk('text', { class: 'dbs-cohort-ms', x: ml, y: cy + 4 }, gg).textContent = 'fewer than 4 months observed'; return; }
    const xsv = pts.map(p => x(p[1].ratio));
    mk('line', { class: 'dbs-cohort-span', x1: Math.min(...xsv), x2: Math.max(...xsv), y1: cy, y2: cy }, gg);
    pts.forEach(([m, v]) => {
      const d = mk('circle', { class: 'dbs-cohort-md', cx: x(v.ratio), cy, r: 5, fill: 'var(--mc)', 'data-m': m }, gg);
      d.addEventListener('pointerenter', e => placeTip('<b>' + c.label + ' · month ' + m + '</b><em>' + M.label + '</em><strong>' + (v.ratio * 100).toFixed(1) + '%</strong><dl><dt>Cohort MRR</dt><dd>' + usd.format(v.cell.mrr) + '</dd><dt>Customers</dt><dd>' + v.cell.logos + '</dd></dl>', e.clientX, e.clientY));
      d.addEventListener('pointerleave', hideTip);
    });
  });
  $('.dbs-cohort-mtitle').textContent = M.label + ' at milestones';
}

/* ---------------- drivers ---------------- */
function fillSelect() { $('.dbs-cohort-csel').innerHTML = COH.map((c, i) => '<option value="' + i + '"' + (i === st.drv ? ' selected' : '') + '>' + c.label + ' · ' + (12 - i) + ' months</option>').join(''); }
function drawDrivers() {
  const svg = $('.dbs-cohort-drv'), box = svg.parentNode, W = box.clientWidth, H = box.clientHeight;
  const S = series(st.plan), rows = S[st.drv];
  if (W && H) {
    svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H); svg.textContent = '';
    const up = Math.max(...rows.map(r => r.exp), 1), dn = Math.max(...rows.map(r => r.con + r.chn), 1);
    const span = up + dn, ml = 54, mr = 46, mt = 16, mb = 28, iw = W - ml - mr, ih = H - mt - mb;
    const y = v => mt + (up - v) / span * ih, band = iw / 12, bw = Math.min(26, band * .55);
    const g = mk('g', { class: 'dbs-cohort-gl' }, svg);
    [up, up / 2, 0, -dn / 2, -dn].forEach(v => { mk('line', { x1: ml, x2: ml + iw, y1: y(v), y2: y(v) }, g); mk('text', { x: ml - 6, y: y(v) + 3.5, 'text-anchor': 'end' }, g).textContent = (v > 0 ? '+' : v < 0 ? MINUS : '') + kf(Math.abs(v)); });
    for (let m = 0; m < 12; m++) mk('text', { x: ml + band * m + band / 2, y: H - 8, 'text-anchor': 'middle' }, g).textContent = 'M' + m;
    const nlo = Math.min(...rows.map(r => r.mrr)), nhi = Math.max(...rows.map(r => r.mrr)), pad = (nhi - nlo) * .15 + 1;
    const yn = v => mt + (1 - (v - nlo + pad) / (nhi - nlo + pad * 2)) * ih;
    rows.forEach((r, m) => {
      const x0 = ml + band * m + (band - bw) / 2;
      if (r.exp) mk('rect', { class: 'dbs-cohort-b dbs-cohort-bp', x: x0, width: bw, y: y(r.exp), height: y(0) - y(r.exp), rx: 2, style: '--i:' + m }, svg);
      if (r.con) mk('rect', { class: 'dbs-cohort-b dbs-cohort-bc', x: x0, width: bw, y: y(0), height: y(-r.con) - y(0), rx: 2, style: '--i:' + m }, svg);
      if (r.chn) mk('rect', { class: 'dbs-cohort-b dbs-cohort-bx', x: x0, width: bw, y: y(-r.con), height: y(-r.con - r.chn) - y(-r.con), rx: 2, style: '--i:' + m }, svg);
    });
    mk('line', { class: 'dbs-cohort-zero', x1: ml, x2: ml + iw, y1: y(0), y2: y(0) }, svg);
    const pts = rows.map((r, m) => [ml + band * m + band / 2, yn(r.mrr)]);
    mk('path', { class: 'dbs-cohort-nl', pathLength: 1, d: 'M' + pts.map(p => p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join('L') }, svg);
    pts.forEach(p => mk('circle', { class: 'dbs-cohort-nd', cx: p[0], cy: p[1], r: 3 }, svg));
    mk('text', { class: 'dbs-cohort-nt', x: ml + iw + 6, y: pts[pts.length - 1][1] + 4 }, svg).textContent = kf(rows[rows.length - 1].mrr);
    mk('text', { class: 'dbs-cohort-nt', x: pts[0][0] + 8, y: pts[0][1] + 16 }, svg).textContent = 'MRR ' + kf(rows[0].mrr);
    rows.forEach((r, m) => {
      const h = mk('rect', { class: 'dbs-cohort-hit', x: ml + band * m, y: mt, width: band, height: ih }, svg);
      h.addEventListener('pointermove', e => placeTip('<b>' + COH[st.drv].label + ' · month ' + m + '</b><em>Cohort MRR ' + usd.format(r.mrr) + '</em><dl><dt>Expansion</dt><dd>+' + usd.format(r.exp) + '</dd><dt>Contraction</dt><dd>' + MINUS + usd.format(r.con) + '</dd><dt>Churn</dt><dd>' + MINUS + usd.format(r.chn) + '</dd><dt>Net</dt><dd>' + (r.exp - r.con - r.chn >= 0 ? '+' : MINUS) + usd.format(Math.abs(r.exp - r.con - r.chn)) + '</dd></dl>', e.clientX, e.clientY));
      h.addEventListener('pointerleave', hideTip);
    });
  }
  const sum = k => rows.reduce((s, r) => s + r[k], 0), start = rows[0].mrr, end = rows[rows.length - 1].mrr;
  $('.dbs-cohort-dsum').innerHTML = [['Starting MRR', usd.format(start), ''], ['Expansion', '+' + usd.format(sum('exp')), 'var(--dbs-cohort-pos)'], ['Contraction', MINUS + usd.format(sum('con')), 'color-mix(in oklch, var(--dbs-cohort-neg) 55%, var(--dbs-cohort-mid))'], ['Churn', MINUS + usd.format(sum('chn')), 'var(--dbs-cohort-neg)'], ['Today · NRR ' + (end / start * 100).toFixed(1) + '%', usd.format(end), 'var(--dbs-cohort-p1)']]
    .map(([l, v, c]) => '<div><span>' + (c ? '<i style="--sc:' + c + '"></i>' : '') + l + '</span><b>' + v + '</b></div>').join('');
}
$('.dbs-cohort-csel').addEventListener('change', e => { st.drv = +e.target.value; drawDrivers(); });

/* ---------------- controls, views ---------------- */
function setRadio(group, v) {
  st[group] = v;
  qa('[data-group="' + group + '"] [role="radio"]').forEach(b => { const on = b.dataset.v === v; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; });
  root.querySelector('.dbs-cohort-unit [data-v="abs"]').textContent = st.metric === 'logo' ? '#' : '$';
  $('.dbs-cohort-title h2').textContent = METRIC[st.metric].label + ' by signup cohort';
  refresh();
}
function refresh() { paintGrid(); if (st.view === 'grid') drawCurves(); if (st.view === 'miles') drawMiles(); if (st.view === 'drivers') drawDrivers(); }
function switchView(v) {
  if (v === st.view) return;
  const apply = () => {
    st.view = v;
    qa('.dbs-cohort-tabs [role="tab"]').forEach(b => { const on = b.dataset.view === v; b.setAttribute('aria-selected', on); b.tabIndex = on ? 0 : -1; });
    qa('.dbs-cohort-view').forEach(s => { s.hidden = s.dataset.view !== v; });
    refresh();
  };
  const main = $('.dbs-cohort-main');
  if (document.startViewTransition && !reduced()) {
    main.style.viewTransitionName = 'dbs-cohort-main';
    const vt = document.startViewTransition(apply); vt.ready.catch(() => {}); vt.finished.finally(() => { main.style.viewTransitionName = ''; });
  } else apply();
}
root.addEventListener('click', e => {
  const t = e.target;
  const tab = t.closest('.dbs-cohort-tabs [role="tab"]'); if (tab) { switchView(tab.dataset.view); return; }
  const rb = t.closest('[data-group] [role="radio"]'); if (rb) { setRadio(rb.parentNode.dataset.group, rb.dataset.v); return; }
  const up = t.closest('[data-unpin]'); if (up) { togglePin(+up.dataset.unpin); }
});
root.addEventListener('keydown', e => {
  if (e.key === 'Escape') { hideTip(); return; }
  const g = e.target.closest('[data-group]');
  if (g && /Arrow(Left|Right)/.test(e.key)) {
    const bs = Array.from(g.querySelectorAll('[role="radio"]')), i = bs.findIndex(b => b.dataset.v === st[g.dataset.group]), j = (i + (e.key === 'ArrowRight' ? 1 : bs.length - 1)) % bs.length;
    e.preventDefault(); setRadio(g.dataset.group, bs[j].dataset.v); bs[j].focus();
  }
  if (e.target.closest('.dbs-cohort-tabs') && /Arrow/.test(e.key)) {
    const tabs = qa('.dbs-cohort-tabs [role="tab"]'), i = tabs.indexOf(document.activeElement), j = (i + (/Down|Right/.test(e.key) ? 1 : tabs.length - 1)) % tabs.length;
    e.preventDefault(); tabs[j].focus(); switchView(tabs[j].dataset.view);
  }
});
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (st.view === 'grid') drawCurves(); if (st.view === 'miles') drawMiles(); if (st.view === 'drivers') drawDrivers();
});
ro.observe($('.dbs-cohort-cbox')); ro.observe($('.dbs-cohort-mbox')); ro.observe($('.dbs-cohort-dbox'));

buildGrid();
fillSelect();
paintGrid();
drawCurves();

