@property --dbs-dunning-sweep { syntax: "<percentage>"; inherits: false; initial-value: 0%; }
@keyframes dbs-dunning-reveal { from { --dbs-dunning-sweep: 0%; } to { --dbs-dunning-sweep: 100%; } }
@keyframes dbs-dunning-flowdash { to { stroke-dashoffset: -48; } }
@keyframes dbs-dunning-in { from { opacity: 0; transform: translateY(6px); } }
@keyframes dbs-dunning-spin { to { rotate: 360deg; } }
@keyframes dbs-dunning-grow { from { transform: scaleY(0); } }
@keyframes dbs-dunning-flash { 0% { background: color-mix(in oklch, var(--dbs-dunning-rec) 22%, transparent); } }
@keyframes dbs-dunning-vt-out { to { opacity: 0; } }
@keyframes dbs-dunning-vt-in { from { opacity: 0; clip-path: inset(0 0 100% 0); } to { clip-path: inset(0 0 0 0); } }
html:has(.dbs-dunning)::view-transition-old(dbs-dunning-main) { animation: 120ms linear both dbs-dunning-vt-out; }
html:has(.dbs-dunning)::view-transition-new(dbs-dunning-main) { animation: 480ms cubic-bezier(.65,0,.35,1) both dbs-dunning-vt-in; }

.dbs-dunning *, .dbs-dunning *::before, .dbs-dunning *::after { box-sizing: border-box; }
.dbs-dunning {
  --dbs-dunning-bg: oklch(0.982 0.003 95);
  --dbs-dunning-ink: oklch(0.24 0.008 95);
  --dbs-dunning-rec: oklch(0.6 0.13 158);
  --dbs-dunning-lost: oklch(0.57 0.19 24);
  --dbs-dunning-dun: oklch(0.77 0.14 72);

  --dbs-dunning-card: white;
  --dbs-dunning-side: color-mix(in oklch, var(--dbs-dunning-ink), black 8%);
  --dbs-dunning-trunk: color-mix(in oklch, var(--dbs-dunning-ink) 16%, var(--dbs-dunning-bg));
  --dbs-dunning-line: color-mix(in oklch, var(--dbs-dunning-ink) 10%, transparent);
  --dbs-dunning-line-2: color-mix(in oklch, var(--dbs-dunning-ink) 20%, transparent);
  --dbs-dunning-mute: color-mix(in oklch, var(--dbs-dunning-ink) 54%, var(--dbs-dunning-bg));
  --dbs-dunning-faint: color-mix(in oklch, var(--dbs-dunning-ink) 4%, transparent);
  --dbs-dunning-ease: cubic-bezier(.65, 0, .35, 1);
  --dbs-dunning-out: cubic-bezier(.16, 1, .3, 1);
  --dbs-dunning-spring: linear(0, .008, .031 2.6%, .126 5.6%, .553 16.3%, .735 21.5%, .862 26.8%, .945 32.4%, .991 38.4%, 1.012 44.9%, 1.016 52.3%, 1.006 66.7%, 1);
  --dbs-dunning-mono: ui-monospace, Menlo, "SF Mono", Consolas, monospace;

  position: relative; width: 100%; height: var(--dbs-dunning-h, 680px); container-type: inline-size; overflow: hidden;
  border-radius: 14px; border: 1px solid var(--dbs-dunning-line); background: var(--dbs-dunning-bg); color: var(--dbs-dunning-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; font-variant-numeric: tabular-nums; -webkit-font-smoothing: antialiased;
  accent-color: var(--dbs-dunning-ink);

  button, input { font: inherit; color: inherit; }
  :focus-visible { outline: 2px solid var(--dbs-dunning-ink); outline-offset: 2px; }
  svg { display: block; }
  [data-s="rec"] { --sc: var(--dbs-dunning-rec); } [data-s="dun"] { --sc: var(--dbs-dunning-dun); } [data-s="lost"] { --sc: var(--dbs-dunning-lost); } [data-s="rate"] { --sc: var(--dbs-dunning-ink); }

  .dbs-dunning-app { height: 100%; display: grid; grid-template-columns: 204px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side head" "side main"; }
  .dbs-dunning-side { grid-area: side; display: flex; flex-direction: column; gap: 22px; padding: 18px 12px; background: var(--dbs-dunning-side); color: oklch(0.93 0.004 95); }
  .dbs-dunning-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px;
    svg { width: 30px; height: 30px; padding: 6px; flex: none; border-radius: 8px; background: var(--dbs-dunning-rec); fill: none; stroke: white; stroke-width: 1.8; stroke-linecap: round; }
    b { display: block; font-weight: 680; } small { display: block; font-size: 11px; opacity: .6; }
  }
  .dbs-dunning-nav { display: grid; gap: 2px;
    button { position: relative; display: flex; align-items: center; gap: 10px; height: 36px; padding: 0 10px; border: 0; border-radius: 8px; background: none; color: oklch(0.93 0.004 95 / .62); cursor: pointer; text-align: left; font-weight: 550; transition: color .2s, background .2s;
      svg { width: 16px; height: 16px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
      &:hover { color: white; background: oklch(1 0 0 / .06); }
      &[aria-selected="true"] { color: white; background: oklch(1 0 0 / .1); }
    }
    :focus-visible { outline-color: white; }
  }
  .dbs-dunning-count { margin-left: auto; font: 600 10.5px var(--dbs-dunning-mono); font-style: normal; padding: 1px 7px; border-radius: 99px; background: color-mix(in oklch, var(--dbs-dunning-dun) 30%, transparent); color: var(--dbs-dunning-dun); }
  .dbs-dunning-sched { margin-top: auto; padding: 0 6px; font-size: 11.5px;
    p { margin: 0 0 8px; font-size: 10.5px; letter-spacing: .09em; text-transform: uppercase; opacity: .55; font-weight: 650; }
    ol { list-style: none; margin: 0; padding: 0; display: grid; gap: 5px; position: relative; }
    ol::before { content: ""; position: absolute; left: 13px; top: 6px; bottom: 6px; width: 1px; background: oklch(1 0 0 / .15); }
    li { position: relative; display: flex; gap: 10px; align-items: center; opacity: .82; }
    b { width: 27px; flex: none; text-align: center; font: 600 10px var(--dbs-dunning-mono); padding: 2px 0; border-radius: 5px; background: var(--dbs-dunning-side); box-shadow: inset 0 0 0 1px oklch(1 0 0 / .18); }
  }

  .dbs-dunning-head { grid-area: head; display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 12px 18px; padding: 18px 20px 12px; }
  .dbs-dunning-title h2 { margin: 0; font-size: clamp(19px, 2.1cqi, 25px); font-weight: 680; letter-spacing: -.022em; line-height: 1.1; text-wrap: balance; }
  .dbs-dunning-sub { margin: 4px 0 0; color: var(--dbs-dunning-mute); }
  .dbs-dunning-ctrls { display: flex; flex-wrap: wrap; gap: 8px; }
  .dbs-dunning-seg { display: flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--dbs-dunning-faint); box-shadow: inset 0 0 0 1px var(--dbs-dunning-line);
    button { border: 0; background: none; padding: 4px 11px; border-radius: 6px; font-weight: 580; color: var(--dbs-dunning-mute); cursor: pointer; transition: background .2s, color .2s, box-shadow .2s;
      &[aria-checked="true"] { background: var(--dbs-dunning-card); color: var(--dbs-dunning-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbs-dunning-ink) 18%, transparent); }
    }
