  .dbs-dunning-view { flex: 1; min-height: 0; }
  .dbs-dunning-view[hidden] { display: none !important; }
  .dbs-dunning-panel { background: var(--dbs-dunning-card); border: 1px solid var(--dbs-dunning-line); border-radius: 12px; min-width: 0; box-shadow: 0 1px 2px color-mix(in oklch, var(--dbs-dunning-ink) 5%, transparent); }
  .dbs-dunning-ph { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 8px; padding: 12px 14px 4px;
    h3 { margin: 0; font-size: 11px; font-weight: 680; letter-spacing: .08em; text-transform: uppercase; color: var(--dbs-dunning-mute); }
  }
  .dbs-dunning-key { display: flex; flex-wrap: wrap; gap: 4px 12px; list-style: none; margin: 0; padding: 0; font-size: 11.5px; color: var(--dbs-dunning-mute);
    li { display: flex; align-items: center; gap: 6px; } li::before { content: ""; width: 9px; height: 9px; border-radius: 3px; background: var(--sc); }
    li[data-s="rate"]::before { height: 2px; }
  }

  .dbs-dunning-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; flex: none; }
  .dbs-dunning-kpi { position: relative; overflow: hidden; padding: 11px 14px 12px; border-radius: 12px; background: var(--dbs-dunning-card); border: 1px solid var(--dbs-dunning-line);
    &::after { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; background: var(--sc, var(--dbs-dunning-ink)); transform-origin: left; transform: scaleX(var(--f, 1)); transition: transform .8s var(--dbs-dunning-spring); }
    h4 { margin: 0; font-size: 10.5px; font-weight: 680; letter-spacing: .08em; text-transform: uppercase; color: var(--dbs-dunning-mute); }
    p { margin: 3px 0 0; font-size: clamp(19px, 2.2cqi, 26px); font-weight: 680; letter-spacing: -.03em; line-height: 1.1; }
    small { display: block; margin-top: 2px; font-size: 11.5px; color: var(--dbs-dunning-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  }

  .dbs-dunning-v-flow { display: grid; gap: 12px; grid-template-columns: minmax(0, 1fr) 264px; }
  .dbs-dunning-fp { display: flex; flex-direction: column; min-height: 330px; }
  .dbs-dunning-fbox { position: relative; flex: 1; min-height: 280px; }
  .dbs-dunning-flow { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible;
    -webkit-mask: linear-gradient(90deg, #000 var(--dbs-dunning-sweep), transparent calc(var(--dbs-dunning-sweep) + 8%));
    mask: linear-gradient(90deg, #000 var(--dbs-dunning-sweep), transparent calc(var(--dbs-dunning-sweep) + 8%));
    animation: dbs-dunning-reveal 1.5s var(--dbs-dunning-ease) .1s both;
