    .dbs-dunning-tr { fill: var(--dbs-dunning-trunk); }
    .dbs-dunning-rr { fill: color-mix(in oklch, var(--dbs-dunning-rec) 55%, transparent); }
    .dbs-dunning-rd { fill: color-mix(in oklch, var(--dbs-dunning-dun) 55%, transparent); }
    .dbs-dunning-rl { fill: color-mix(in oklch, var(--dbs-dunning-lost) 60%, transparent); }
