@keyframes dbs-funnel-in { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbs-funnel-grow { from { transform: scaleY(0); } }
@keyframes dbs-funnel-growx { from { transform: scaleX(0); } }
@keyframes dbs-funnel-pulse { 0% { --dbs-funnel-glow: 1; } 100% { --dbs-funnel-glow: 0; } }
@keyframes dbs-funnel-vt-out { to { opacity: 0; filter: blur(6px); } }
@keyframes dbs-funnel-vt-in { from { opacity: 0; filter: blur(6px); } }
html:has(.dbs-funnel)::view-transition-old(dbs-funnel-main) { animation: 160ms ease-in both dbs-funnel-vt-out; }
html:has(.dbs-funnel)::view-transition-new(dbs-funnel-main) { animation: 360ms cubic-bezier(.16,1,.3,1) both dbs-funnel-vt-in; }

.dbs-funnel *, .dbs-funnel *::before, .dbs-funnel *::after { box-sizing: border-box; }
.dbs-funnel {
  --dbs-funnel-bg: oklch(0.165 0.006 115);
  --dbs-funnel-fg: oklch(0.955 0.012 110);
  --dbs-funnel-lime: oklch(0.91 0.2 124);
  --dbs-funnel-drop: oklch(0.6 0.015 95);

  --dbs-funnel-panel: color-mix(in oklch, var(--dbs-funnel-bg), var(--dbs-funnel-fg) 3.5%);
  --dbs-funnel-line: color-mix(in oklch, var(--dbs-funnel-fg) 9%, transparent);
  --dbs-funnel-line-2: color-mix(in oklch, var(--dbs-funnel-fg) 17%, transparent);
  --dbs-funnel-mute: color-mix(in oklch, var(--dbs-funnel-fg) 52%, var(--dbs-funnel-bg));
  --dbs-funnel-faint: color-mix(in oklch, var(--dbs-funnel-fg) 5%, transparent);
  --dbs-funnel-lime-soft: color-mix(in oklch, var(--dbs-funnel-lime) 16%, transparent);
  --dbs-funnel-ease: cubic-bezier(.16, 1, .3, 1);
  --dbs-funnel-spring: linear(0, .009, .037 2.4%, .153 5.2%, .629 15.4%, .807 20.7%, .923 26.1%, .99 32.1%, 1.022 38.6%, 1.03 45.9%, 1.016 58.5%, 1.003 75%, 1);
  --dbs-funnel-mono: ui-monospace, Menlo, "SF Mono", Consolas, monospace;

  position: relative; width: 100%; height: var(--dbs-funnel-h, 680px); container-type: inline-size; overflow: hidden;
  border-radius: 14px; background: var(--dbs-funnel-bg); color: var(--dbs-funnel-fg); color-scheme: dark;
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; font-variant-numeric: tabular-nums; -webkit-font-smoothing: antialiased;
  accent-color: var(--dbs-funnel-lime);

  button { font: inherit; color: inherit; }
  :focus-visible { outline: 2px solid var(--dbs-funnel-lime); outline-offset: 2px; }
  svg { display: block; }

  .dbs-funnel-app { height: 100%; display: grid; grid-template-rows: auto auto minmax(0, 1fr); }
  .dbs-funnel-top { position: relative; display: flex; align-items: center; gap: 16px; padding: 12px 18px; border-bottom: 1px solid var(--dbs-funnel-line); }
  .dbs-funnel-brand { display: flex; align-items: center; gap: 10px; margin-right: auto;
    svg { width: 30px; height: 30px; padding: 5px; border-radius: 50%; background: var(--dbs-funnel-lime); fill: none; stroke: var(--dbs-funnel-bg); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
    b { display: block; font-weight: 700; letter-spacing: -.01em; line-height: 1.1; } small { display: block; font-size: 11px; color: var(--dbs-funnel-mute); }
  }
  .dbs-funnel-tabs { position: absolute; left: 50%; translate: -50% 0; display: flex; padding: 3px; border-radius: 99px; background: var(--dbs-funnel-faint); box-shadow: inset 0 0 0 1px var(--dbs-funnel-line);
    button { padding: 5px 14px; border: 0; border-radius: 99px; background: none; color: var(--dbs-funnel-mute); font-weight: 600; cursor: pointer; white-space: nowrap; transition: color .2s, background .3s var(--dbs-funnel-ease);
      &[aria-selected="true"] { background: var(--dbs-funnel-fg); color: var(--dbs-funnel-bg); }
      &:hover:not([aria-selected="true"]) { color: var(--dbs-funnel-fg); }
    }
  }
  .dbs-funnel-seg { display: flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--dbs-funnel-faint); box-shadow: inset 0 0 0 1px var(--dbs-funnel-line);
    button { border: 0; background: none; padding: 4px 10px; border-radius: 6px; font: 600 12px var(--dbs-funnel-mono); color: var(--dbs-funnel-mute); cursor: pointer;
      &[aria-checked="true"] { background: var(--dbs-funnel-lime-soft); color: var(--dbs-funnel-lime); }
    }
  }
  .dbs-funnel-bar { display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 10px 16px; padding: 14px 18px 10px; }
  .dbs-funnel-title h2 { margin: 0; font-size: clamp(20px, 2.4cqi, 28px); font-weight: 700; letter-spacing: -.03em; line-height: 1; text-wrap: balance; }
  .dbs-funnel-sub { margin: 5px 0 0; color: var(--dbs-funnel-mute); font-size: 12.5px; }
  .dbs-funnel-chips { display: flex; flex-wrap: wrap; gap: 6px;
    button { display: inline-flex; align-items: center; gap: 7px; padding: 4px 11px 4px 9px; border-radius: 99px; border: 1px solid var(--dbs-funnel-line-2); background: none; font-size: 12px; font-weight: 580; color: var(--dbs-funnel-mute); cursor: pointer; transition: all .25s var(--dbs-funnel-ease);
      &::before { content: ""; width: 8px; height: 8px; border-radius: 50%; border: 1.5px solid currentColor; transition: background .2s, border-color .2s; }
      &[aria-pressed="true"] { color: var(--dbs-funnel-fg); border-color: color-mix(in oklch, var(--dbs-funnel-lime) 45%, transparent); &::before { background: var(--dbs-funnel-lime); border-color: var(--dbs-funnel-lime); } }
    }
  }

  .dbs-funnel-main { min-height: 0; overflow: auto; padding: 0 18px 16px; display: flex; flex-direction: column; gap: 12px; scrollbar-width: thin; scrollbar-color: var(--dbs-funnel-line-2) transparent; }
  .dbs-funnel-view { flex: 1; min-height: 0; }
  .dbs-funnel-view[hidden] { display: none !important; }
  .dbs-funnel-panel { background: var(--dbs-funnel-panel); border: 1px solid var(--dbs-funnel-line); border-radius: 12px; min-width: 0; }
  .dbs-funnel-ph { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; flex-wrap: wrap; padding: 12px 14px 4px;
    h3 { margin: 0; font-size: 11px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--dbs-funnel-mute); }
  }
  .dbs-funnel-med { margin: 0; font-size: 12px; color: var(--dbs-funnel-mute); b { color: var(--dbs-funnel-lime); font-weight: 650; } }

  .dbs-funnel-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1px; flex: none; border-radius: 12px; overflow: hidden; background: var(--dbs-funnel-line); border: 1px solid var(--dbs-funnel-line); }
  .dbs-funnel-kpi { padding: 10px 14px; background: var(--dbs-funnel-panel); animation: dbs-funnel-in .5s var(--dbs-funnel-ease) backwards; animation-delay: calc(var(--i) * 60ms);
    h4 { margin: 0; font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--dbs-funnel-mute); }
    p { margin: 2px 0 0; font-size: clamp(18px, 2.1cqi, 24px); font-weight: 650; letter-spacing: -.025em; line-height: 1.15; }
    small { display: block; font-size: 11.5px; color: var(--dbs-funnel-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    &:nth-child(3) p { color: var(--dbs-funnel-lime); }
  }

  .dbs-funnel-v-fun { display: grid; gap: 12px; grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr); grid-template-rows: minmax(210px, 1fr) auto; grid-template-areas: "cv cv" "ttc ch"; }
  .dbs-funnel-cvp { grid-area: cv; position: relative; display: flex; flex-direction: column; min-height: 0; overflow: hidden;
    --pool: 108px;
    background: radial-gradient(120% 90% at 100% 50%, color-mix(in oklch, var(--dbs-funnel-lime) 7%, transparent), transparent 60%), var(--dbs-funnel-panel);
  }
  .dbs-funnel-cvbox { position: relative; flex: 1; min-height: 140px; }
  .dbs-funnel-cv { position: absolute; inset: 0; width: 100%; height: 100%; display: block; cursor: crosshair; }
  .dbs-funnel-pool { position: absolute; right: 0; top: 0; bottom: 0; width: var(--pool); display: grid; place-content: center; text-align: center; pointer-events: none;
    b { font-size: 26px; font-weight: 700; letter-spacing: -.03em; color: var(--dbs-funnel-lime); line-height: 1;
      text-shadow: 0 0 calc(var(--dbs-funnel-glow) * 22px) color-mix(in oklch, var(--dbs-funnel-lime) calc(var(--dbs-funnel-glow) * 90%), transparent); }
    span { font-size: 10.5px; letter-spacing: .1em; text-transform: uppercase; color: var(--dbs-funnel-mute); }
    &.is-hit b { animation: dbs-funnel-pulse .9s var(--dbs-funnel-ease); }
  }
  .dbs-funnel-strip { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)) var(--pool); border-top: 1px solid var(--dbs-funnel-line);
    li { min-width: 0; }
    button { width: 100%; height: 100%; display: grid; gap: 1px; padding: 9px 10px 10px; border: 0; border-left: 1px solid var(--dbs-funnel-line); background: none; text-align: left; cursor: default; transition: background .2s;
      &:hover, &:focus-visible, &.is-hot { background: var(--dbs-funnel-faint); }
      span { font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--dbs-funnel-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
      b { font-size: clamp(15px, 1.9cqi, 21px); font-weight: 650; letter-spacing: -.02em; }
      small { font: 11px var(--dbs-funnel-mono); color: var(--dbs-funnel-mute); white-space: nowrap; }
      small em { font-style: normal; color: var(--dbs-funnel-lime); }
    }
    li:first-child button { border-left: 0; }
    .dbs-funnel-poolc { display: grid; place-content: center; padding: 8px; border-left: 1px solid var(--dbs-funnel-line); font: 11px var(--dbs-funnel-mono); color: var(--dbs-funnel-mute); text-align: center; }
  }

  .dbs-funnel-ttc { grid-area: ttc; display: flex; flex-direction: column; min-height: 0; }
  .dbs-funnel-hbox { position: relative; height: 136px; }
  .dbs-funnel-hist { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible;
    .dbs-funnel-hb { fill: color-mix(in oklch, var(--dbs-funnel-lime) 55%, var(--dbs-funnel-bg)); transform-box: fill-box; transform-origin: 50% 100%; animation: dbs-funnel-grow .6s var(--dbs-funnel-spring) backwards; animation-delay: calc(var(--i) * 22ms); transition: fill .2s; }
    .dbs-funnel-hb.is-end { fill: var(--dbs-funnel-lime); }
    .dbs-funnel-hg:hover .dbs-funnel-hb { fill: var(--dbs-funnel-fg); }
    .dbs-funnel-hg rect.dbs-funnel-hit { fill: transparent; }
    .dbs-funnel-gl line { stroke: var(--dbs-funnel-line); } .dbs-funnel-gl text { font: 10px var(--dbs-funnel-mono); fill: var(--dbs-funnel-mute); }
    .dbs-funnel-medl { stroke: var(--dbs-funnel-fg); stroke-dasharray: 2 3; } .dbs-funnel-medt { font: 600 10px var(--dbs-funnel-mono); fill: var(--dbs-funnel-fg); }
    .dbs-funnel-trial { fill: color-mix(in oklch, var(--dbs-funnel-fg) 4%, transparent); }
  }
  .dbs-funnel-chp { grid-area: ch; display: flex; flex-direction: column; min-height: 0; }
  .dbs-funnel-chl { list-style: none; margin: 0; padding: 4px 8px 10px; display: grid; gap: 2px;
    li { display: grid; grid-template-columns: minmax(0, 1fr) 54px 46px; gap: 2px 10px; align-items: center; padding: 3px 6px; border-radius: 7px; font-size: 12px; transition: opacity .3s;
      &.is-off { opacity: .35; }
      span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
      b { font: 600 11.5px var(--dbs-funnel-mono); text-align: right; } em { font: 11.5px var(--dbs-funnel-mono); font-style: normal; color: var(--dbs-funnel-mute); text-align: right; }
      i { grid-column: 1 / -1; height: 4px; border-radius: 2px; background: var(--dbs-funnel-faint); overflow: hidden; }
      i::before { content: ""; display: block; height: 100%; width: calc(var(--w) * 100%); background: var(--dbs-funnel-lime); border-radius: 2px; transform-origin: left; animation: dbs-funnel-growx .8s var(--dbs-funnel-ease) backwards; animation-delay: calc(var(--i) * 60ms); }
    }
  }

  /* cohorts */
  .dbs-funnel-tblp { height: 100%; display: flex; flex-direction: column; min-height: 0; }
  .dbs-funnel-tscroll { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbs-funnel-line-2) transparent; }
  .dbs-funnel-table { width: 100%; border-collapse: collapse;
    th { position: sticky; top: 0; z-index: 1; background: var(--dbs-funnel-panel); text-align: left; padding: 9px 12px; font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dbs-funnel-mute); border-bottom: 1px solid var(--dbs-funnel-line);
      button { border: 0; background: none; padding: 0; font: inherit; letter-spacing: inherit; text-transform: inherit; color: inherit; cursor: pointer; }
      &[aria-sort="ascending"] button::after { content: " ↑"; } &[aria-sort="descending"] button::after { content: " ↓"; }
      &[aria-sort]:not([aria-sort="none"]) { color: var(--dbs-funnel-fg); }
    }
    td { padding: 9px 12px; border-bottom: 1px solid var(--dbs-funnel-line); white-space: nowrap; }
    tbody tr:hover { background: var(--dbs-funnel-faint); }
  }
  .dbs-funnel-n { text-align: right !important; font-family: var(--dbs-funnel-mono); font-size: 12px; }
  .dbs-funnel-prog { margin-left: 8px; font: 600 10px var(--dbs-funnel-mono); padding: 1px 6px; border-radius: 4px; background: var(--dbs-funnel-faint); color: var(--dbs-funnel-mute); letter-spacing: .04em; }
  .dbs-funnel-pb { display: flex; align-items: center; gap: 10px; min-width: 160px;
    i { flex: 1; height: 8px; border-radius: 4px; background: var(--dbs-funnel-faint); position: relative; overflow: hidden; }
    i::before { content: ""; position: absolute; inset: 0 auto 0 0; width: calc(var(--w) * 100%); background: var(--dbs-funnel-lime); border-radius: 4px; }
    b { font: 600 12px var(--dbs-funnel-mono); width: 46px; text-align: right; }
    &.is-partial i::before { background: repeating-linear-gradient(-45deg, var(--dbs-funnel-lime) 0 4px, color-mix(in oklch, var(--dbs-funnel-lime) 45%, transparent) 4px 8px); }
  }
  @supports (animation-timeline: view()) {
    .dbs-funnel-table tbody tr { animation: dbs-funnel-in linear both; animation-timeline: view(); animation-range: entry 0% entry 80%; }
  }

  /* channels */
  .dbs-funnel-cmp { height: 100%; display: flex; flex-direction: column; min-height: 0; }
  .dbs-funnel-cmbox { position: relative; flex: 1; min-height: 260px; }
  .dbs-funnel-cm { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible;
    .dbs-funnel-gl line { stroke: var(--dbs-funnel-line); } .dbs-funnel-gl text { font: 10.5px var(--dbs-funnel-mono); fill: var(--dbs-funnel-mute); }
    .dbs-funnel-cb { fill: color-mix(in oklch, var(--dbs-funnel-fg) 16%, transparent); transform-box: fill-box; transform-origin: 0 50%; animation: dbs-funnel-growx .8s var(--dbs-funnel-spring) backwards; animation-delay: calc(var(--i) * 70ms); }
    .dbs-funnel-cd { fill: var(--dbs-funnel-lime); stroke: var(--dbs-funnel-bg); stroke-width: 2; animation: dbs-funnel-in .5s var(--dbs-funnel-ease) backwards; animation-delay: calc(var(--i) * 70ms + 400ms); }
    .dbs-funnel-cl { font-size: 12px; fill: var(--dbs-funnel-fg); font-weight: 560; }
    .dbs-funnel-cv2 { font: 600 11px var(--dbs-funnel-mono); fill: var(--dbs-funnel-lime); }
    .dbs-funnel-cn { font: 11px var(--dbs-funnel-mono); fill: var(--dbs-funnel-mute); }
    .dbs-funnel-row:hover .dbs-funnel-cb { fill: color-mix(in oklch, var(--dbs-funnel-fg) 28%, transparent); }
    .dbs-funnel-row.is-off { opacity: .3; }
  }
  .dbs-funnel-key { display: flex; gap: 12px; list-style: none; margin: 0; padding: 0; font-size: 11px; color: var(--dbs-funnel-mute);
    li { display: flex; align-items: center; gap: 6px; }
    li[data-k="bar"]::before { content: ""; width: 14px; height: 8px; border-radius: 2px; background: color-mix(in oklch, var(--dbs-funnel-fg) 20%, transparent); }
    li[data-k="dot"]::before { content: ""; width: 9px; height: 9px; border-radius: 50%; background: var(--dbs-funnel-lime); }
  }
  .dbs-funnel-insight { margin: 0; padding: 10px 14px 14px; color: var(--dbs-funnel-mute); font-size: 12.5px; text-wrap: pretty; b { color: var(--dbs-funnel-fg); } }

  .dbs-funnel-tip { position: absolute; z-index: 30; left: 0; top: 0; width: 220px; padding: 10px 12px; border-radius: 10px; pointer-events: none;
    background: color-mix(in oklch, var(--dbs-funnel-bg), var(--dbs-funnel-fg) 10%); border: 1px solid var(--dbs-funnel-line-2); box-shadow: 0 16px 40px -14px black;
    font-size: 12px; opacity: 0; transition: opacity .15s;
    &.is-on { opacity: 1; }
    b { display: block; font-weight: 650; } em { display: block; font-style: normal; color: var(--dbs-funnel-mute); font-size: 11px; margin-bottom: 6px; }
    strong { display: block; font-size: 20px; letter-spacing: -.02em; color: var(--dbs-funnel-lime); margin-bottom: 4px; }
    dl { margin: 0; display: grid; grid-template-columns: 1fr auto; gap: 2px 10px; dt { color: var(--dbs-funnel-mute); } dd { margin: 0; text-align: right; font-family: var(--dbs-funnel-mono); font-size: 11.5px; } }
  }

  @container (max-width: 959px) {
    .dbs-funnel-tabs { position: static; translate: none; }
    .dbs-funnel-v-fun { grid-template-columns: minmax(0, 1fr); grid-template-rows: 300px auto auto; grid-template-areas: "cv" "ttc" "ch"; }
    .dbs-funnel-view { flex: none; }
    .dbs-funnel-tblp, .dbs-funnel-cmp { height: auto; }
    .dbs-funnel-tscroll { max-height: 440px; }
  }
  @container (max-width: 759px) {
    .dbs-funnel-top { flex-wrap: wrap; padding: 10px 12px; gap: 10px; }
    .dbs-funnel-brand span { display: none; }
    .dbs-funnel-tabs { order: 3; width: 100%; justify-content: space-between; button { flex: 1; padding: 5px 8px; } }
    .dbs-funnel-bar { padding: 12px 12px 8px; }
    .dbs-funnel-main { padding: 0 12px 12px; }
    .dbs-funnel-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .dbs-funnel-cvp { --pool: 72px; }
    .dbs-funnel-pool b { font-size: 19px; }
    .dbs-funnel-strip button { padding: 8px 6px; }
    .dbs-funnel-strip small { display: none; }
    .dbs-funnel-hide-s { display: none; }
  }
  @container (max-width: 440px) {
    .dbs-funnel-strip span { font-size: 9px; letter-spacing: .02em; }
    .dbs-funnel-strip b { font-size: 13px; }
    .dbs-funnel-strip .dbs-funnel-poolc { display: none; }
    .dbs-funnel-strip { grid-template-columns: repeat(5, minmax(0, 1fr)); }
  }
}

@media (prefers-reduced-motion: reduce) {
  .dbs-funnel *, .dbs-funnel *::before, .dbs-funnel *::after { animation: none !important; transition-duration: .01ms !important; transition-delay: 0s !important; }
}

