const $ = s => root.querySelector(s), qa = s => Array.from(root.querySelectorAll(s));
const NS = 'http://www.w3.org/2000/svg';
const mk = (tag, attrs, parent) => { const e = document.createElementNS(NS, tag); for (const k in attrs) e.setAttribute(k, attrs[k]); if (parent) parent.appendChild(e); return e; };
const reduced = () => matchMedia('(prefers-reduced-motion: reduce)').matches;
const num = new Intl.NumberFormat('en-US');
const usd = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
const pct = (a, b, d = 1) => b ? (a / b * 100).toFixed(d) + '%' : '—';
function prng(a) { return function () { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }

/* ---------------- data ---------------- */
const STAGES = ['Started trial', 'Activated', 'Collaborated', 'Hit a limit', 'Paid'];
const STAGE_HINT = ['Signed up for the 14-day trial', 'Created a first board', 'Invited at least one teammate', 'Reached a free-plan limit', 'Paid the first invoice'];
const CH = [
  { k: 'organic', label: 'Organic search', vol: [180, 240], p: [.62, .48, .55, .52] },
  { k: 'social', label: 'Paid social', vol: [120, 200], p: [.48, .36, .44, .40] },
  { k: 'referral', label: 'Referral', vol: [40, 70], p: [.74, .62, .63, .61] },
  { k: 'partner', label: 'Partner marketplace', vol: [30, 60], p: [.66, .52, .58, .55] },
  { k: 'outbound', label: 'Outbound', vol: [15, 30], p: [.55, .58, .62, .47] }
];
const WEEK0 = new Date(2026, 6, 6);
const WEEKS = Array.from({ length: 12 }, (_, i) => { const d = new Date(WEEK0); d.setDate(d.getDate() + i * 7); return d; });
