    mk('rect', { class: 'dbs-funnel-cb', x: ml, y: cy - 9, width: xb(o.t) - ml, height: 18, rx: 4, style: '--i:' + i }, gg);
    mk('circle', { class: 'dbs-funnel-cd', cx: xr(o.r), cy, r: 7, style: '--i:' + i }, gg);
    mk('text', { class: 'dbs-funnel-cv2', x: xr(o.r) + 12, y: cy + 4 }, gg).textContent = (o.r * 100).toFixed(1) + '%';
    const hit = mk('rect', { x: 0, y: cy - rh / 2, width: W, height: rh, fill: 'transparent' }, gg);
    hit.addEventListener('pointermove', e => placeTip('<b>' + o.c.label + '</b><em>Last ' + st.range + ' weeks</em><strong>' + (o.r * 100).toFixed(1) + '%</strong><dl><dt>Trials</dt><dd>' + num.format(o.t) + '</dd><dt>Paid</dt><dd>' + num.format(o.p) + '</dd><dt>New MRR</dt><dd>' + usd.format(o.p * ARPA) + '</dd></dl>', e.clientX, e.clientY));
    hit.addEventListener('pointerleave', hideTip);
  });
  const best = rows.slice().sort((a, b) => b.r - a.r)[0], big = rows.slice().sort((a, b) => b.t - a.t)[0];
  $('.dbs-funnel-insight').innerHTML = '<b>' + best.c.label + '</b> converts best at ' + (best.r * 100).toFixed(1) + '% but brings ' + num.format(best.t) + ' trials; <b>' + big.c.label + '</b> brings the most volume (' + num.format(big.t) + ') and converts at ' + (big.r * 100).toFixed(1) + '%. Deselected channels stay on this chart, dimmed, so the comparison is always complete.';
}

/* ---------------- wiring ---------------- */
function renderChips() { $('.dbs-funnel-chips').innerHTML = CH.map(c => '<button data-ch="' + c.k + '" aria-pressed="' + st.ch.has(c.k) + '">' + c.label + '</button>').join(''); }
function refresh() {
  renderKpis(); FX.G = FX.W ? geom() : null;
  FX.maxTrials = agg(new Set(CH.map(c => c.k))).s[0];
  $('[data-paid]').textContent = num.format(agg().s[4]);
  if (st.view === 'funnel') { drawHist(); renderChannels(); if (FX.still) drawStatic(); }
  if (st.view === 'cohorts') renderCohorts();
  if (st.view === 'channels') drawCompare();
}
function switchView(v) {
  if (v === st.view) return;
