  else apply();
}
root.addEventListener('click', e => {
  const t = e.target;
  const tab = t.closest('.dbs-funnel-tabs [role="tab"]'); if (tab) { switchView(tab.dataset.view); return; }
  const rb = t.closest('[data-group="range"] [role="radio"]');
  if (rb) { st.range = +rb.dataset.v; qa('[data-group="range"] [role="radio"]').forEach(b => { const on = b === rb; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; }); refresh(); return; }
  const ch = t.closest('[data-ch]');
  if (ch) { const k = ch.dataset.ch; if (st.ch.has(k) && st.ch.size === 1) return; st.ch.has(k) ? st.ch.delete(k) : st.ch.add(k); ch.setAttribute('aria-pressed', st.ch.has(k)); refresh(); return; }
  const srt = t.closest('[data-sort]'); if (srt) { const k = srt.dataset.sort; st.sort = { key: k, dir: st.sort.key === k ? -st.sort.dir : -1 }; renderCohorts(); }
});
root.addEventListener('keydown', e => {
  if (e.key === 'Escape') { hideTip(); return; }
  if (e.target.closest('.dbs-funnel-tabs') && /Arrow(Left|Right)/.test(e.key)) {
    const tabs = qa('.dbs-funnel-tabs [role="tab"]'), i = tabs.indexOf(document.activeElement), j = (i + (e.key === 'ArrowRight' ? 1 : tabs.length - 1)) % tabs.length;
    e.preventDefault(); tabs[j].focus(); switchView(tabs[j].dataset.view);
  }
  const g = e.target.closest('[data-group="range"]');
  if (g && /Arrow(Left|Right)/.test(e.key)) {
    const bs = Array.from(g.querySelectorAll('[role="radio"]')), i = bs.findIndex(b => +b.dataset.v === st.range), j = (i + (e.key === 'ArrowRight' ? 1 : bs.length - 1)) % bs.length;
    e.preventDefault(); bs[j].click(); bs[j].focus();
  }
});
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); stop(); return; }
  if (st.view === 'funnel') { resize(); drawHist(); }
  if (st.view === 'channels') drawCompare();
});
ro.observe(cv.parentNode); ro.observe($('.dbs-funnel-hbox')); ro.observe($('.dbs-funnel-cmbox'));

readColors();
FX.still = reduced();
renderChips();
resize();
refresh();
start();

