@property --dbs-meter-sweep { syntax: "<angle>"; inherits: false; initial-value: 0deg; }
@property --dbs-meter-fill { syntax: "<number>"; inherits: true; initial-value: 0; }
@keyframes dbs-meter-sweep-in { from { --dbs-meter-sweep: 0deg; } }
@keyframes dbs-meter-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dbs-meter-fade { from { opacity: 0; } }
@keyframes dbs-meter-grow { from { transform: scaleY(0); } }
@keyframes dbs-meter-up { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbs-meter-vt-out { to { opacity: 0; transform: translateY(-8px); } }
@keyframes dbs-meter-vt-in { from { opacity: 0; transform: translateY(10px); } }
html:has(.dbs-meter)::view-transition-old(dbs-meter-main) { animation: 140ms ease-in both dbs-meter-vt-out; }
html:has(.dbs-meter)::view-transition-new(dbs-meter-main) { animation: 380ms cubic-bezier(.2,.8,.2,1) both dbs-meter-vt-in; }

.dbs-meter *, .dbs-meter *::before, .dbs-meter *::after { box-sizing: border-box; }
.dbs-meter {
