  --dbs-meter-faint: color-mix(in oklch, var(--dbs-meter-ink) 4%, transparent);
  --dbs-meter-acc-soft: color-mix(in oklch, var(--dbs-meter-accent) 10%, transparent);
  --dbs-meter-ease: cubic-bezier(.2, .8, .2, 1);
