/* ---------------- invoice ---------------- */
function renderInvoice() {
  const inv = invoice(st.mode);
  let i = 0;
  const row = (cls, a, b, c, d) => '<tr class="' + cls + '" style="--i:' + (i++) + '"><td>' + a + '</td><td class="dbs-meter-n">' + b + '</td><td class="dbs-meter-n dbs-meter-hide-s">' + c + '</td><td class="dbs-meter-n">' + d + '</td></tr>';
  let h = row('dbs-meter-grp', 'Growth plan · platform fee', '1', money.format(PLATFORM), money.format(PLATFORM));
  inv.parts.forEach(p => {
    h += row('dbs-meter-grp', p.m.label + ' · ' + p.m.fmt(st.mode === 'mtd' ? p.P.mtd : p.P.end) + (p.m.cumulative ? '' : ' avg'), '', '', money.format(p.pr.total));
    p.pr.rows.forEach(t => { if (t.qty <= 0 && t.lo > 0) return; h += row('dbs-meter-sub2', t.label, p.m.fmt(t.qty), t.rate ? '$' + t.rate.toFixed(3) + ' ' + p.m.perL : 'included', money.format(t.cost)); });
  });
  $('.dbs-meter-lines tbody').innerHTML = h;
  const over = inv.total > BUDGET;
  $('.dbs-meter-sum').innerHTML = '<span>Subtotal</span><b>' + money.format(inv.sub) + '</b><span>Estimated tax · 8.0%</span><b>' + money.format(inv.tax) + '</b>' +
    '<span class="dbs-meter-total">' + (st.mode === 'mtd' ? 'Month to date' : 'Projected total') + '</span><b data-total>' + money.format(inv.total) + '</b>' +
    '<div class="dbs-meter-budget"><div class="dbs-meter-bbl"><span>Against the ' + money.format(BUDGET) + ' monthly budget</span><b>' + (inv.total / BUDGET * 100).toFixed(1) + '%</b></div><div class="dbs-meter-bb' + (over ? ' is-over' : '') + '" style="--dbs-meter-fill:' + Math.min(1, inv.total / BUDGET).toFixed(4) + '"><i></i><em></em></div></div>';
}

/* ---------------- wiring ---------------- */
function refresh() { renderTabs(); if (st.view === 'meter') { drawChart(); renderAlert(); renderTiers(); } else renderInvoice(); }
function select(key) {
  const toInv = key === 'inv';
  const same = toInv ? st.view === 'invoice' : st.view === 'meter' && st.meter === +key;
  if (same) return;
  const apply = () => {
    st.view = toInv ? 'invoice' : 'meter';
    if (!toInv) st.meter = +key;
    qa('.dbs-meter-tabs [role="tab"]').forEach(b => { const on = b.dataset.meter === String(key); b.setAttribute('aria-selected', on); b.tabIndex = on ? 0 : -1; });
    qa('.dbs-meter-view').forEach(s => { s.hidden = s.dataset.view !== st.view; });
    refresh();
  };
  const main = $('.dbs-meter-main');
  if (document.startViewTransition && !reduced()) { main.style.viewTransitionName = 'dbs-meter-main'; const vt = document.startViewTransition(apply); vt.ready.catch(() => {}); vt.finished.finally(() => { main.style.viewTransitionName = ''; }); }
  else apply();
}
root.addEventListener('click', e => {
  const t = e.target;
  const tab = t.closest('.dbs-meter-tabs [role="tab"]'); if (tab) { select(tab.dataset.meter); return; }
  const md = t.closest('[data-mode]'); if (md) { st.mode = md.dataset.mode; qa('[data-mode]').forEach(b => { const on = b === md; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; }); renderInvoice(); }
});
root.addEventListener('keydown', e => {
  if (e.key === 'Escape') { hideTip(); return; }
  if (e.target.closest('.dbs-meter-tabs') && /Arrow(Left|Right)|Home|End/.test(e.key)) {
    const tabs = qa('.dbs-meter-tabs [role="tab"]'), i = tabs.indexOf(document.activeElement);
    const j = e.key === 'Home' ? 0 : e.key === 'End' ? tabs.length - 1 : (i + (e.key === 'ArrowRight' ? 1 : tabs.length - 1)) % tabs.length;
    e.preventDefault(); tabs[j].focus(); select(tabs[j].dataset.meter);
  }
  if (e.target.closest('.dbs-meter-mode') && /Arrow(Left|Right)/.test(e.key)) { const n = st.mode === 'proj' ? 'mtd' : 'proj'; const b = root.querySelector('[data-mode="' + n + '"]'); b.click(); b.focus(); e.preventDefault(); }
});
$('.dbs-meter-wr').addEventListener('input', e => {
  st.change = +e.target.value;
  $('.dbs-meter-wv').textContent = (st.change > 0 ? '+' : st.change < 0 ? '−' : '+') + Math.abs(st.change) + '%';
  refresh();
});
const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } if (st.view === 'meter') drawChart(); });
ro.observe($('.dbs-meter-cbox'));

refresh();

css:
@property --dbs-admin-shift { syntax: "<length>"; inherits: false; initial-value: 0px; }
@keyframes dbs-admin-march { to { --dbs-admin-shift: 28.284px; } }
@keyframes dbs-admin-in { from { opacity: 0; transform: translateY(6px); } }
@keyframes dbs-admin-blink { 50% { opacity: .35; } }
@keyframes dbs-admin-vt-out { to { opacity: 0; } }
@keyframes dbs-admin-vt-in { from { opacity: 0; transform: translateY(8px); } }
html:has(.dbs-admin)::view-transition-old(dbs-admin-main) { animation: 120ms linear both dbs-admin-vt-out; }
html:has(.dbs-admin)::view-transition-new(dbs-admin-main) { animation: 340ms cubic-bezier(.2,.8,.2,1) both dbs-admin-vt-in; }

.dbs-admin *, .dbs-admin *::before, .dbs-admin *::after { box-sizing: border-box; }
.dbs-admin {
  --dbs-admin-bg: oklch(0.175 0.007 60);
  --dbs-admin-fg: oklch(0.93 0.01 80);
  --dbs-admin-haz: oklch(0.76 0.17 58);
  --dbs-admin-ok: oklch(0.78 0.12 155);

  --dbs-admin-deep: color-mix(in oklch, var(--dbs-admin-bg), black 30%);
  --dbs-admin-panel: color-mix(in oklch, var(--dbs-admin-bg), var(--dbs-admin-fg) 3.5%);
  --dbs-admin-line: color-mix(in oklch, var(--dbs-admin-fg) 10%, transparent);
  --dbs-admin-line-2: color-mix(in oklch, var(--dbs-admin-fg) 18%, transparent);
  --dbs-admin-mute: color-mix(in oklch, var(--dbs-admin-fg) 54%, var(--dbs-admin-bg));
  --dbs-admin-faint: color-mix(in oklch, var(--dbs-admin-fg) 5%, transparent);
  --dbs-admin-trial: oklch(0.76 0.1 235); --dbs-admin-due: oklch(0.83 0.14 86); --dbs-admin-susp: oklch(0.67 0.18 26);
  --dbs-admin-ease: cubic-bezier(.2, .8, .2, 1);
  --dbs-admin-spring: linear(0, .009, .037 2.4%, .153 5.2%, .629 15.4%, .807 20.7%, .923 26.1%, .99 32.1%, 1.022 38.6%, 1.03 45.9%, 1.016 58.5%, 1.003 75%, 1);
  --dbs-admin-mono: ui-monospace, Menlo, "SF Mono", Consolas, monospace;

  position: relative; width: 100%; height: var(--dbs-admin-h, 680px); container-type: inline-size; overflow: hidden;
  border-radius: 14px; background: var(--dbs-admin-deep); color: var(--dbs-admin-fg); color-scheme: dark;
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; font-variant-numeric: tabular-nums; -webkit-font-smoothing: antialiased;
  accent-color: var(--dbs-admin-haz);

  button, input, select { font: inherit; color: inherit; }
  :focus-visible { outline: 2px solid var(--dbs-admin-haz); outline-offset: 2px; }
  svg { display: block; }
  kbd { font: 600 10px var(--dbs-admin-mono); padding: 1px 5px; border-radius: 4px; border: 1px solid var(--dbs-admin-line-2); color: var(--dbs-admin-mute); }
  [data-s="active"] { --sc: var(--dbs-admin-ok); } [data-s="trial"] { --sc: var(--dbs-admin-trial); } [data-s="due"] { --sc: var(--dbs-admin-due); } [data-s="susp"] { --sc: var(--dbs-admin-susp); }

  /* hazard frame: visible only while impersonating */
  &::before { content: ""; position: absolute; inset: 0; opacity: 0;
    background: repeating-linear-gradient(45deg, var(--dbs-admin-haz) 0 10px, var(--dbs-admin-deep) 10px 20px); background-position: var(--dbs-admin-shift) 0;
    animation: dbs-admin-march 1.2s linear infinite paused; transition: opacity .35s; }
  &.is-imp::before { opacity: 1; animation-play-state: running; }
  &.is-imp.is-off::before { animation-play-state: paused; }

  .dbs-admin-app { position: absolute; inset: 0; z-index: 1; overflow: hidden; border-radius: 14px; background: var(--dbs-admin-bg);
    display: grid; grid-template-columns: 68px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "rail banner" "rail main";
    transition: inset .55s var(--dbs-admin-spring), border-radius .4s; }
  &.is-imp .dbs-admin-app { inset: 7px; border-radius: 8px; }
  &.is-imp .dbs-admin-nav button { opacity: .35; pointer-events: none; }

  .dbs-admin-rail { grid-area: rail; display: flex; flex-direction: column; align-items: center; gap: 18px; padding: 14px 0; background: var(--dbs-admin-deep); border-right: 1px solid var(--dbs-admin-line); }
  .dbs-admin-logo svg { width: 32px; height: 32px; padding: 6px; border-radius: 9px; background: var(--dbs-admin-fg); fill: none; stroke: var(--dbs-admin-bg); stroke-width: 1.6; stroke-linejoin: round; stroke-linecap: round; }
  .dbs-admin-nav { display: grid; gap: 6px;
    button { width: 54px; display: grid; justify-items: center; gap: 3px; padding: 7px 0 6px; border: 0; border-radius: 10px; background: none; color: var(--dbs-admin-mute); cursor: pointer; font-size: 10px; font-weight: 600; letter-spacing: .02em; transition: color .2s, background .2s;
      svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
      &:hover { color: var(--dbs-admin-fg); background: var(--dbs-admin-faint); }
      &[aria-selected="true"] { color: var(--dbs-admin-fg); background: color-mix(in oklch, var(--dbs-admin-haz) 14%, transparent); svg { stroke: var(--dbs-admin-haz); } }
    }
  }
  .dbs-admin-me { margin-top: auto; i { width: 30px; height: 30px; display: grid; place-items: center; border-radius: 50%; font: 700 10.5px system-ui; font-style: normal; background: color-mix(in oklch, var(--dbs-admin-haz) 22%, var(--dbs-admin-bg)); color: var(--dbs-admin-haz); } }

  /* banner */
  .dbs-admin-banner { grid-area: banner; display: none; align-items: center; gap: 12px; padding: 8px 14px; background: var(--dbs-admin-haz); color: oklch(0.2 0.02 60);
    transition: display .4s allow-discrete, translate .45s var(--dbs-admin-spring), opacity .3s; translate: 0 -100%; opacity: 0;
    p { margin: 0; flex: 1; min-width: 0; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    b { font-weight: 750; } span, em, code { margin-left: 8px; } em { font-style: normal; font-weight: 700; text-transform: uppercase; font-size: 10.5px; letter-spacing: .08em; padding: 1px 6px; border-radius: 4px; background: oklch(0.2 0.02 60 / .12); }
    code { font: 600 11px var(--dbs-admin-mono); }
    time { font: 750 15px var(--dbs-admin-mono); letter-spacing: -.02em; }
    .dbs-admin-hz { width: 18px; height: 18px; fill: oklch(0.2 0.02 60); stroke: var(--dbs-admin-haz); stroke-width: 1.4; stroke-linecap: round; flex: none; }
    &.is-low time { animation: dbs-admin-blink 1s steps(2) infinite; }
  }
  &.is-imp .dbs-admin-banner { display: flex; translate: 0 0; opacity: 1; }
  @starting-style { &.is-imp .dbs-admin-banner { translate: 0 -100%; opacity: 0; } }
  .dbs-admin-end { border: 0; border-radius: 7px; padding: 5px 10px; background: oklch(0.2 0.02 60); color: var(--dbs-admin-haz); font-weight: 700; font-size: 12px; cursor: pointer; display: flex; align-items: center; gap: 8px;
    kbd { color: inherit; border-color: color-mix(in oklch, var(--dbs-admin-haz) 40%, transparent); }
    &:focus-visible { outline-color: oklch(0.2 0.02 60); }
  }

  .dbs-admin-main { grid-area: main; position: relative; min-height: 0; overflow: hidden; }
  .dbs-admin-view { height: 100%; }
  .dbs-admin-view[hidden] { display: none !important; }

  /* accounts: list + detail */
  .dbs-admin-v-acc { display: grid; grid-template-columns: 300px minmax(0, 1fr); }
  .dbs-admin-listp { display: flex; flex-direction: column; min-height: 0; border-right: 1px solid var(--dbs-admin-line); }
  .dbs-admin-lh { padding: 12px 12px 8px; display: grid; gap: 8px; }
  .dbs-admin-search { display: flex; align-items: center; gap: 8px; height: 34px; padding: 0 8px 0 10px; border-radius: 9px; background: var(--dbs-admin-faint); box-shadow: inset 0 0 0 1px var(--dbs-admin-line);
    svg { width: 14px; height: 14px; flex: none; fill: none; stroke: var(--dbs-admin-mute); stroke-width: 1.5; stroke-linecap: round; }
    input { flex: 1; min-width: 0; border: 0; outline: none; background: none; }
    &:focus-within { box-shadow: inset 0 0 0 1.5px var(--dbs-admin-haz); kbd { opacity: 0; } }
  }
  .dbs-admin-chips { display: flex; flex-wrap: wrap; gap: 5px;
    button { display: inline-flex; align-items: center; gap: 6px; padding: 2px 9px 2px 7px; border-radius: 99px; border: 1px solid var(--dbs-admin-line); background: none; font-size: 11.5px; font-weight: 580; color: var(--dbs-admin-mute); cursor: pointer; transition: all .2s;
      &::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--sc); opacity: .4; }
      &[aria-pressed="true"] { color: var(--dbs-admin-fg); border-color: var(--dbs-admin-line-2); background: var(--dbs-admin-faint); &::before { opacity: 1; } }
      em { font: 10.5px var(--dbs-admin-mono); font-style: normal; opacity: .7; }
    }
  }
  .dbs-admin-lstat { margin: 0; font: 11px var(--dbs-admin-mono); color: var(--dbs-admin-mute); }
  .dbs-admin-list { list-style: none; margin: 0; padding: 0 6px 10px; overflow: auto; flex: 1; min-height: 0; outline: none; scrollbar-width: thin; scrollbar-color: var(--dbs-admin-line-2) transparent;
    li[role="option"] { display: grid; grid-template-columns: 8px minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 8px 8px; border-radius: 8px; cursor: pointer; transition: background .15s;
      &:hover { background: var(--dbs-admin-faint); }
      &[aria-selected="true"] { background: color-mix(in oklch, var(--dbs-admin-haz) 13%, transparent); box-shadow: inset 2px 0 0 var(--dbs-admin-haz); }
    }
    .dbs-admin-none { padding: 24px 12px; color: var(--dbs-admin-mute); text-align: center; }
  }
  .dbs-admin-list:focus-visible li[aria-selected="true"] { box-shadow: inset 2px 0 0 var(--dbs-admin-haz), inset 0 0 0 1px var(--dbs-admin-haz); }
  .dbs-admin-st { width: 8px; height: 8px; border-radius: 50%; background: var(--sc); box-shadow: 0 0 0 3px color-mix(in oklch, var(--sc) 18%, transparent); }
  .dbs-admin-ln { min-width: 0; b { display: block; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } small { display: block; font: 10.5px var(--dbs-admin-mono); color: var(--dbs-admin-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } }
  .dbs-admin-lr { text-align: right; small { display: block; font: 11px var(--dbs-admin-mono); color: var(--dbs-admin-mute); } }
  .dbs-admin-plan { font: 650 10px var(--dbs-admin-mono); font-style: normal; letter-spacing: .04em; text-transform: uppercase; padding: 1px 5px; border-radius: 4px; background: var(--dbs-admin-faint); color: var(--dbs-admin-mute); }
  .dbs-admin-plan[data-plan="Enterprise"] { color: var(--dbs-admin-haz); background: color-mix(in oklch, var(--dbs-admin-haz) 14%, transparent); }

  .dbs-admin-detail { display: flex; flex-direction: column; min-height: 0; min-width: 0; }
  .dbs-admin-dh { display: flex; flex-wrap: wrap; align-items: start; gap: 10px 16px; padding: 16px 18px 12px; }
  .dbs-admin-back { display: none; width: 30px; height: 30px; place-items: center; border: 0; border-radius: 8px; background: var(--dbs-admin-faint); cursor: pointer; flex: none;
    svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; } }
  .dbs-admin-dt { flex: 1; min-width: 200px; }
  .dbs-admin-did { margin: 0; font: 11px var(--dbs-admin-mono); color: var(--dbs-admin-mute); }
  .dbs-admin-dname { margin: 2px 0 2px; font-size: clamp(18px, 2.1cqi, 24px); font-weight: 680; letter-spacing: -.02em; line-height: 1.15; text-wrap: balance; outline: none; }
  .dbs-admin-dmeta { margin: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 4px 12px; font-size: 12px; color: var(--dbs-admin-mute); }
  .dbs-admin-pill { display: inline-flex; align-items: center; gap: 6px; padding: 1px 8px; border-radius: 99px; font-size: 11.5px; font-weight: 650; color: var(--sc); background: color-mix(in oklch, var(--sc) 14%, transparent);
    &::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--sc); } }
  .dbs-admin-dact { display: flex; flex-wrap: wrap; gap: 8px; }
  .dbs-admin-btn { display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 12px; border: 0; border-radius: 8px; font-weight: 650; font-size: 12.5px; cursor: pointer; white-space: nowrap; transition: filter .2s, transform .25s var(--dbs-admin-spring), background .2s;
    svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; }
    &:active:not(:disabled) { transform: scale(.96); }
    &:disabled { opacity: .45; cursor: not-allowed; }
  }
  .dbs-admin-primary { background: var(--dbs-admin-haz); color: oklch(0.2 0.02 60); &:hover:not(:disabled) { filter: brightness(1.07); } }
  .dbs-admin-ghost { background: var(--dbs-admin-faint); box-shadow: inset 0 0 0 1px var(--dbs-admin-line); &:hover { background: var(--dbs-admin-line); } }
  .dbs-admin-dtabs { display: flex; gap: 2px; padding: 0 18px; border-bottom: 1px solid var(--dbs-admin-line);
    button { position: relative; padding: 8px 10px 10px; border: 0; background: none; color: var(--dbs-admin-mute); font-weight: 600; cursor: pointer;
      em { font: 10.5px var(--dbs-admin-mono); font-style: normal; margin-left: 4px; opacity: .7; }
      &::after { content: ""; position: absolute; left: 10px; right: 10px; bottom: -1px; height: 2px; background: var(--dbs-admin-haz); scale: 0 1; transition: scale .4s var(--dbs-admin-spring); }
      &[aria-selected="true"] { color: var(--dbs-admin-fg); &::after { scale: 1 1; } }
