    > * { animation: dbs-admin-in .4s var(--dbs-admin-ease) backwards; }
  }
  .dbs-admin-ov { display: grid; gap: 14px; grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); grid-template-areas: "facts usage" "facts flags"; align-items: start; }
