    small { display: block; font: 11px var(--dbs-admin-mono); color: var(--dbs-admin-mute); font-weight: 400; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    i { display: block; height: 4px; margin-top: 6px; border-radius: 2px; background: var(--dbs-admin-faint); overflow: hidden; }
    i::before { content: ""; display: block; height: 100%; width: calc(var(--w) * 100%); background: var(--dbs-admin-fg); border-radius: 2px; }
  }
  .dbs-admin-usage { grid-area: usage; padding: 12px; border-radius: 10px; background: var(--dbs-admin-panel); border: 1px solid var(--dbs-admin-line);
    svg { width: 100%; height: 64px; }
    .dbs-admin-ub { fill: color-mix(in oklch, var(--dbs-admin-fg) 30%, transparent); transition: fill .15s; }
    .dbs-admin-ub.is-we { fill: color-mix(in oklch, var(--dbs-admin-fg) 16%, transparent); }
    .dbs-admin-ub:hover { fill: var(--dbs-admin-haz); }
    p { margin: 6px 0 0; font: 11px var(--dbs-admin-mono); color: var(--dbs-admin-mute); b { color: var(--dbs-admin-fg); } }
  }
  .dbs-admin-flagsec { grid-area: flags; padding: 12px; border-radius: 10px; background: var(--dbs-admin-panel); border: 1px solid var(--dbs-admin-line);
    ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
    li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 0 10px; align-items: center; padding: 5px 0; }
    li span { font-weight: 560; font-size: 12.5px; } li small { grid-column: 1; font: 10.5px var(--dbs-admin-mono); color: var(--dbs-admin-mute); }
  }
  .dbs-admin-sw { grid-row: span 2; position: relative; width: 34px; height: 20px; border: 0; border-radius: 99px; background: var(--dbs-admin-line-2); cursor: pointer; transition: background .25s;
    &::after { content: ""; position: absolute; left: 3px; top: 3px; width: 14px; height: 14px; border-radius: 50%; background: var(--dbs-admin-fg); transition: translate .35s var(--dbs-admin-spring); }
    &[aria-checked="true"] { background: var(--dbs-admin-haz); &::after { translate: 14px 0; background: oklch(0.2 0.02 60); } }
  }
