  else if (k === 'cancel') closeSheet();
  else if (k === 'end') endImp('manual');
  else if (k === 'back') { setPane('list'); list.focus(); }
  else if (k === 'reset') { const a = ACC[st.sel]; log(now(), ME, 'security', 'Password reset email sent to ' + a.owner.email, a); renderDetail(); toast('Reset link sent to ' + a.owner.email + '.'); }
  else if (k === 'cust-new') toast('Documents created here belong to ' + ACC[st.imp ? st.imp.a.i : st.sel].name + ' and are attributed to ' + ME + '.');
});
$('.dbs-admin-search input').addEventListener('input', e => { st.q = e.target.value; renderList(); });
root.addEventListener('keydown', e => {
  const typing = /INPUT|SELECT|TEXTAREA/.test(e.target.tagName);
  if (e.key === 'Escape') {
    hideTip();
    if (sheet.classList.contains('is-open')) { e.preventDefault(); closeSheet(); return; }
    if (st.imp) { e.preventDefault(); endImp('manual'); return; }
    if (typing && e.target.type === 'search' && e.target.value) return;
    return;
  }
  if (e.key === '/' && !typing && !st.imp && st.view === 'accounts') { e.preventDefault(); setPane('list'); $('.dbs-admin-search input').focus(); return; }
  if (e.target.closest('.dbs-admin-nav') && /Arrow/.test(e.key)) {
    const tabs = qa('.dbs-admin-nav [role="tab"]'), i = tabs.indexOf(document.activeElement), j = (i + (/Down|Right/.test(e.key) ? 1 : tabs.length - 1)) % tabs.length;
    e.preventDefault(); tabs[j].focus(); switchView(tabs[j].dataset.view);
  }
  if (e.target.closest('.dbs-admin-dtabs') && /Arrow(Left|Right)/.test(e.key)) {
    const tabs = qa('.dbs-admin-dtabs [role="tab"]'), i = tabs.findIndex(b => b.dataset.tab === st.tab), j = (i + (e.key === 'ArrowRight' ? 1 : tabs.length - 1)) % tabs.length;
    e.preventDefault(); st.tab = tabs[j].dataset.tab; renderTab(); tabs[j].focus();
  }
});
root.addEventListener('click', e => { const ch = e.target.closest('[data-type]'); if (ch) { const t = ch.dataset.type; st.types.has(t) ? st.types.delete(t) : st.types.add(t); renderAudit(); } });

/* pause the marching frame when off screen */
const io = new IntersectionObserver(es => { if (!root.isConnected) { io.disconnect(); clearInterval(timer); return; } root.classList.toggle('is-off', !es[0].isIntersecting); });
io.observe(root);
const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } if (st.view === 'accounts' && st.tab === 'overview') drawUsage(ACC[st.sel]); });
ro.observe($('.dbs-admin-dbody'));

renderChips();
renderList();
renderDetail();
